//! Sparse-trie-as-overlay commitment: reth's [`SparseStateTrie`] computes the
//! per-block state root on the hot path, fetching every trie node it needs
//! from the flat store through the Phase-1 cursor factories — while the flat
//! engine itself is only written by the background follower, off the slot
//! deadline.
//!
//! Shape per block:
//!  * During execution the state hook streams touched keys in; the worker
//!    inserts them as [`LeafUpdate::Touched`] and periodically resolves the
//!    resulting blinded-path targets with classic multiproofs generated by
//!    [`reth_trie::proof::Proof`] over `FlatTrieCursorFactory` /
//!    `FlatHashedCursorFactory` (read lock only). That pre-reveals the trie
//!    paths the finish step will need — the same overlap reth's own sparse
//!    trie task gets from its proof workers.
//!  * At finish the *authoritative* net changes (derived from the bundle, not
//!    from hook accumulation) are applied as [`LeafUpdate::Changed`] values,
//!    stragglers are revealed, storage roots promote into account leaves, and
//!    `root()` returns the commitment.
//!
//! Consistency rule: every proof must be generated against the flat state at
//! the block's PARENT. Each fetch re-checks `at_parent` under the same read
//! guard the proof walk uses; if the follower hasn't caught up (or an
//! abandoned candidate is still applied) the pass defers, and the finish path
//! waits — asking the follower to unwind if the parent is in the retained
//! window. Any error falls back to the caller's inline `root_for`.

use crate::{
    FlatShadow,
    cursors::{FlatHashedCursorFactory, FlatTrieCursorFactory},
};
use alloy_primitives::{
    B256, keccak256,
    map::{B256Map, B256Set},
};
use alloy_rlp::{Decodable as _, Encodable as _};
use mpt_flat_poc::{Key, StateOp};
use parking_lot::RwLock;
use reth_trie::{
    BranchNodeMasks, BranchNodeV2, DecodedMultiProofV2, EMPTY_ROOT_HASH, HashedPostState,
    HashedPostStateSorted, HashedStorage, LeafNode, MultiProofTargetsV2, Nibbles, ProofTrieNodeV2,
    ProofV2Target, ProofV2TargetParent, TrieAccount, TrieMask, TrieNodeV2,
    hashed_cursor::HashedPostStateCursorFactory,
    proof::Proof,
    trie_cursor::InMemoryTrieCursorFactory,
    updates::{TrieUpdates, TrieUpdatesSorted},
};
use reth_trie_sparse::{LeafUpdate, SparseStateTrie, TrieNodeEpoch};
use std::{
    sync::mpsc,
    time::{Duration, Instant},
};

/// Newly touched keys that trigger a reveal pass during execution.
const PASS_TARGETS: usize = 8_192;

/// How many times a reveal round may re-fetch already-fetched targets that
/// are still blinded (a first proof can leave a deeper node or a collapse
/// sibling unrevealed) before we give up and fall back.
const STALL_RETRIES: u32 = 3;

/// How long the finish path waits for the follower to bring the flat store to
/// the block's parent before giving up (`TEMPO_FLATMPT_SPARSE_WAIT_MS`).
fn parent_wait() -> Duration {
    static MS: std::sync::OnceLock<u64> = std::sync::OnceLock::new();
    Duration::from_millis(*MS.get_or_init(|| {
        std::env::var("TEMPO_FLATMPT_SPARSE_WAIT_MS")
            .ok()
            .and_then(|s| s.parse().ok())
            .unwrap_or(30_000)
    }))
}

/// Whether the sparse-over-flat commitment runs in root mode (default on;
/// `TEMPO_FLATMPT_SPARSE=0` disables, falling back to inline `root_for`).
pub fn sparse_enabled() -> bool {
    crate::mode() == crate::FlatMode::Root
        && std::env::var("TEMPO_FLATMPT_SPARSE").as_deref() != Ok("0")
}

/// Per-block commitment statistics (logged by the builder).
#[derive(Debug, Default, Clone, Copy)]
pub struct SparseStats {
    /// Reveal passes run while execution was still in progress.
    pub exec_passes: u32,
    /// Passes deferred because the flat store wasn't at the parent yet.
    pub deferred_passes: u32,
    /// Fetch→reveal rounds needed by the finish drain.
    pub finish_rounds: u32,
    /// Account / storage proof targets fetched over the whole block.
    pub account_targets: u64,
    pub storage_targets: u64,
    /// Time spent generating multiproofs over the flat cursors.
    pub proof_ms: u64,
    /// Time spent revealing proof nodes into the sparse trie.
    pub reveal_ms: u64,
    /// Finish-path time spent waiting for the flat store to reach the parent.
    pub wait_parent_ms: u64,
    /// Total finish() latency: the commitment's cost on the slot's hot path.
    pub finish_ms: u64,
    /// Whether this block reused the pooled trie from the previous block.
    pub pool_hit: bool,
    /// Pooled trie memory after finish (MB), 0 if dropped.
    pub trie_mem_mb: u64,
    /// Prewarm batches dropped because the hook channel was full.
    pub hook_dropped: u64,
    /// Finish sub-phases (all inside `finish_ms`): net-change map build,
    /// storage-leaf drain, account promote (incl. storage roots), final
    /// account drain + root hash, overlay build+push.
    pub fin_netmap_ms: u64,
    pub fin_drain_ms: u64,
    pub fin_promote_ms: u64,
    /// Portion of `fin_promote_ms` spent hashing storage subtries.
    pub fin_sroot_ms: u64,
    pub fin_root_ms: u64,
    pub fin_overlay_ms: u64,
}

/// Soundness anchor for a pooled trie's blind regions. A blind path is only
/// guaranteed untouched since the trie's CREATION, so revealing it from a
/// flat snapshot older than that creation state serves pre-update content —
/// silently wrong siblings, wrong root (the r148 block-349 divergence: trie
/// lost at flood end, recreated blind at an empty block, then revealed a
/// 4k-op block from a snapshot 64 blocks behind the creation root).
#[derive(Clone, Copy, Debug)]
enum Anchor {
    /// Trie created fresh while building on this parent root. Blind regions
    /// match flat state only from that root onward; arbitrary-lineage
    /// reveals stay unsound until the follower is known to have reached it.
    Pending(B256),
    /// The follower reached the anchor at this apply sequence; any snapshot
    /// stamped at or after it serves blind regions correctly.
    Satisfied(u64),
}

/// Follower apply sequence, bumped once per applied block (`prune_overlays`).
/// Snapshots are stamped with the value at capture; stamps may lag the true
/// state by a race window, which only ever denies a sound reveal, never
/// permits an unsound one.
static APPLY_SEQ: std::sync::atomic::AtomicU64 = std::sync::atomic::AtomicU64::new(1);

/// Ring of (root, seq) for recently applied blocks, so a Pending anchor can
/// be resolved even when the follower passed it while the trie was checked
/// out of the pool. Unwinds don't rewrite history here: an entry means "flat
/// WAS this state at seq", which is all the anchor check needs on a linear
/// chain; a reorg drops the pooled trie via the root-match rule anyway.
static RECENT_ROOTS: parking_lot::Mutex<std::collections::VecDeque<(B256, u64)>> =
    parking_lot::Mutex::new(std::collections::VecDeque::new());

const RECENT_ROOTS_CAP: usize = 8192;

/// Earliest apply sequence at which the follower held `root`, if tracked.
fn root_seq(root: B256) -> Option<u64> {
    RECENT_ROOTS
        .lock()
        .iter()
        .find(|(r, _)| *r == root)
        .map(|(_, s)| *s)
}

/// The revealed sparse trie carried across blocks, tagged with the state root
/// it represents and its soundness anchor. The next block's worker consumes
/// it iff building on that exact root; at steady state the hot set is already
/// revealed and proof targets collapse to newly-touched keys. A cancelled
/// build (worker dropped mid-block) repools it only if still clean — reveals
/// are parent-state facts, applied leaf updates are not. The follower's
/// per-block root cross-check remains the loud gate against any staleness.
static TRIE_POOL: parking_lot::Mutex<Option<(B256, Anchor, SparseStateTrie)>> =
    parking_lot::Mutex::new(None);

/// The last flat snapshot any worker held, stamped with the apply sequence at
/// capture, carried across blocks like the trie pool: a worker on a pool-hit
/// block whose anchor clears the stamp can reveal from it without ever
/// waiting for the shadow lock.
static SNAP_POOL: parking_lot::Mutex<Option<(mpt_flat_poc::FlatSnapshot, u64)>> =
    parking_lot::Mutex::new(None);

/// One committed-but-not-yet-applied block's effect on the trie, kept so
/// proof fetches for descendants can run against flat-at-an-older-root plus
/// this overlay stack instead of waiting for the background follower
/// (reth's engine-tree pattern). Pushed at sparse finish, pruned as the
/// follower advances; a rebuilt candidate truncates its abandoned sibling.
type OverlayContent =
    std::sync::Arc<parking_lot::RwLock<Option<(TrieUpdatesSorted, HashedPostState)>>>;

struct OverlayBlock {
    parent_root: B256,
    root: B256,
    /// Filled by the finish thread's async overlay build; `None` until then.
    /// The entry itself is pushed synchronously so deque order (and the
    /// supersede-on-same-parent rule) stays deterministic.
    content: OverlayContent,
}

static OVERLAYS: parking_lot::Mutex<std::collections::VecDeque<OverlayBlock>> =
    parking_lot::Mutex::new(std::collections::VecDeque::new());

/// Bound on tracked un-applied blocks; beyond this the oldest is dropped and
/// fetches for deep descendants degrade to waiting for the follower. Sized
/// past the deepest follower lag seen at flood (64 blocks): a fresh trie
/// whose anchor is still pending must be able to proof-walk through the
/// whole un-applied stack instead of stalling on wait_for_parent.
const OVERLAY_CAP: usize = 96;

/// Register a block's overlay slot (synchronously, preserving order); the
/// returned handle is filled by the async overlay build.
fn push_overlay_pending(parent_root: B256, root: B256) -> OverlayContent {
    let content: OverlayContent = std::sync::Arc::new(parking_lot::RwLock::new(None));
    let mut q = OVERLAYS.lock();
    // A candidate rebuilding on the same parent supersedes the abandoned one
    // (and anything stacked on it).
    if let Some(i) = q.iter().position(|e| e.parent_root == parent_root) {
        q.truncate(i);
    }
    q.push_back(OverlayBlock {
        parent_root,
        root,
        content: content.clone(),
    });
    while q.len() > OVERLAY_CAP {
        q.pop_front();
    }
    content
}

/// Merged overlays covering `flat_root` → `parent_root`, if a complete chain
/// is tracked. `None` with equal roots means "no overlay needed". Waits
/// briefly for in-flight overlay builds (a ~10ms async fill); timing out
/// degrades to the caller's wait-for-parent path.
fn overlay_chain(
    flat_root: B256,
    parent_root: B256,
) -> Option<(
    std::sync::Arc<TrieUpdatesSorted>,
    std::sync::Arc<HashedPostStateSorted>,
)> {
    if flat_root == parent_root {
        return None;
    }
    let entries: Vec<(B256, B256, OverlayContent)> = OVERLAYS
        .lock()
        .iter()
        .map(|o| (o.parent_root, o.root, o.content.clone()))
        .collect();
    let mut trie = TrieUpdates::default();
    let mut post = HashedPostState::default();
    let mut at = flat_root;
    let mut found = false;
    for (o_parent, o_root, content) in &entries {
        if *o_parent != at {
            continue;
        }
        let mut ready = false;
        for _ in 0..2_000 {
            {
                let g = content.read();
                if let Some((t, p)) = g.as_ref() {
                    trie.extend_from_sorted(t);
                    post.extend(p.clone());
                    ready = true;
                }
            }
            if ready {
                break;
            }
            std::thread::sleep(std::time::Duration::from_millis(1));
        }
        if !ready {
            return None; // build still in flight after 2s — degrade to waiting
        }
        at = *o_root;
        if at == parent_root {
            found = true;
            break;
        }
    }
    found.then(|| {
        (
            std::sync::Arc::new(trie.into_sorted()),
            std::sync::Arc::new(post.into_sorted()),
        )
    })
}

/// Drop overlays the follower has caught up past. Also the follower-progress
/// tick: bumps the apply sequence, records the reached root, and satisfies a
/// pooled trie's pending anchor when the follower reaches it.
pub(crate) fn prune_overlays(flat_root: B256) {
    let seq = APPLY_SEQ.fetch_add(1, std::sync::atomic::Ordering::SeqCst) + 1;
    {
        let mut ring = RECENT_ROOTS.lock();
        ring.push_back((flat_root, seq));
        while ring.len() > RECENT_ROOTS_CAP {
            ring.pop_front();
        }
    }
    if let Some((_, anchor, _)) = TRIE_POOL.lock().as_mut()
        && let Anchor::Pending(r) = *anchor
        && r == flat_root
    {
        *anchor = Anchor::Satisfied(seq);
    }
    let mut q = OVERLAYS.lock();
    while let Some(front) = q.front() {
        if front.parent_root == flat_root {
            break;
        }
        q.pop_front();
    }
}

/// Map a block's net ops to the `HashedPostState` overlay reth's cursors
/// understand (keys are already hashed in flat-MPT ops). Also serves the
/// payload builder as the block's hashed state: the ops already carry every
/// hashed key, so this avoids re-keccaking the whole bundle on the hot path.
pub fn ops_to_post_state(ops: &[(Key, StateOp)]) -> HashedPostState {
    let mut post = HashedPostState::default();
    for (key, op) in ops {
        let acct = B256::from(*key);
        match op {
            StateOp::SetAccount {
                nonce,
                balance,
                code_hash,
            } => {
                let code_hash = B256::from(*code_hash);
                post.accounts.insert(
                    acct,
                    Some(reth_primitives_traits::Account {
                        nonce: *nonce,
                        balance: *balance,
                        // Same normalization as reth's AccountInfo→Account:
                        // the empty code hash is represented as None.
                        bytecode_hash: (code_hash != mpt_flat_poc::eth::EMPTY_CODE_HASH)
                            .then_some(code_hash),
                    }),
                );
            }
            StateOp::DeleteAccount => {
                post.accounts.insert(acct, None);
                post.storages.insert(acct, HashedStorage::new(true));
            }
            StateOp::WipeStorage => {
                post.storages.insert(acct, HashedStorage::new(true));
            }
            StateOp::SetStorage { slot, value } => {
                let v = alloy_primitives::U256::decode(&mut value.as_slice()).unwrap_or_default();
                post.storages
                    .entry(acct)
                    .or_insert_with(|| HashedStorage::new(false))
                    .storage
                    .insert(B256::from(*slot), v);
            }
            StateOp::DeleteStorage { slot } => {
                post.storages
                    .entry(acct)
                    .or_insert_with(|| HashedStorage::new(false))
                    .storage
                    .insert(B256::from(*slot), alloy_primitives::U256::ZERO);
            }
        }
    }
    post
}

/// Whether reveal nodes come straight from flat records (default) instead of
/// the generic proof walk (`TEMPO_FLATMPT_FAST_REVEAL=0` selects the latter).
fn fast_reveal() -> bool {
    static ON: std::sync::OnceLock<bool> = std::sync::OnceLock::new();
    *ON.get_or_init(|| std::env::var("TEMPO_FLATMPT_FAST_REVEAL").as_deref() != Ok("0"))
}

/// Convert the engine's reveal nodes to V2 proof nodes, folding each
/// extension into its child branch (the V2 representation). The engine
/// guarantees an extension is immediately followed by that branch.
fn to_v2_nodes(
    nodes: Vec<mpt_flat_poc::reveal::RevealNode>,
) -> anyhow::Result<Vec<ProofTrieNodeV2>> {
    use mpt_flat_poc::reveal::{RevealNode as R, RevealRef};
    fn rlp_ref(r: &RevealRef) -> anyhow::Result<reth_trie::RlpNode> {
        Ok(match r {
            RevealRef::Hash(h) => reth_trie::RlpNode::word_rlp(&B256::from(*h)),
            RevealRef::Inline(b) => reth_trie::RlpNode::from_raw(b)
                .ok_or_else(|| anyhow::anyhow!("inline child too long"))?,
        })
    }
    fn nib(p: &[u8]) -> Nibbles {
        Nibbles::from_nibbles(p)
    }
    let mut out = Vec::with_capacity(nodes.len());
    let mut it = nodes.into_iter().peekable();
    while let Some(n) = it.next() {
        match n {
            R::EmptyRoot => out.push(ProofTrieNodeV2 {
                path: Nibbles::default(),
                node: TrieNodeV2::EmptyRoot,
                masks: None,
            }),
            R::Leaf { path, key, value } => out.push(ProofTrieNodeV2 {
                path: nib(&path),
                node: TrieNodeV2::Leaf(LeafNode::new(nib(&key), value)),
                masks: None,
            }),
            R::Branch {
                path,
                children,
                tree_mask,
                hash_mask,
            } => {
                let mut stack = Vec::new();
                let mut state = 0u16;
                for (i, c) in children.iter().enumerate() {
                    if let Some(c) = c {
                        state |= 1 << i;
                        stack.push(rlp_ref(c)?);
                    }
                }
                out.push(ProofTrieNodeV2 {
                    path: nib(&path),
                    node: TrieNodeV2::Branch(BranchNodeV2 {
                        key: Nibbles::default(),
                        stack,
                        state_mask: TrieMask::new(state),
                        branch_rlp_node: None,
                    }),
                    masks: Some(BranchNodeMasks {
                        hash_mask: TrieMask::new(hash_mask),
                        tree_mask: TrieMask::new(tree_mask),
                    }),
                });
            }
            R::Extension { path, key, child } => {
                // Fold with the immediately following child branch.
                let Some(R::Branch {
                    path: bpath,
                    children,
                    tree_mask,
                    hash_mask,
                }) = it.next()
                else {
                    anyhow::bail!("extension at {path:?} not followed by its child branch");
                };
                let mut expect = path.clone();
                expect.extend_from_slice(&key);
                anyhow::ensure!(bpath == expect, "extension child branch path mismatch");
                let mut stack = Vec::new();
                let mut state = 0u16;
                for (i, c) in children.iter().enumerate() {
                    if let Some(c) = c {
                        state |= 1 << i;
                        stack.push(rlp_ref(c)?);
                    }
                }
                out.push(ProofTrieNodeV2 {
                    path: nib(&path),
                    node: TrieNodeV2::Branch(BranchNodeV2 {
                        key: nib(&key),
                        stack,
                        state_mask: TrieMask::new(state),
                        branch_rlp_node: Some(rlp_ref(&child)?),
                    }),
                    masks: Some(BranchNodeMasks {
                        hash_mask: TrieMask::new(hash_mask),
                        tree_mask: TrieMask::new(tree_mask),
                    }),
                });
            }
        }
    }
    Ok(out)
}

/// Reveal nodes for a target set straight from flat records — the fast
/// path (no proof reconstruction). Storage of an absent/opaque account
/// reveals as an empty trie.
fn direct_reveal(
    db: &mpt_flat_poc::FlatSnapshot,
    acct_targets: &B256Map<ProofV2TargetParent>,
    storage_targets: &B256Map<B256Map<ProofV2TargetParent>>,
) -> anyhow::Result<DecodedMultiProofV2> {
    let mut keys: Vec<Key> = acct_targets.keys().map(|k| k.0).collect();
    // Storage targets also need their account's path revealed.
    keys.extend(storage_targets.keys().map(|k| k.0));
    keys.sort_unstable();
    keys.dedup();
    let account_proofs = to_v2_nodes(db.reveal_account_paths(&keys)?)?;
    // Storage reveals fan out across threads: the walk is cheap CPU but the
    // record preads still gain from oversubscription (measured 14k/s @1t →
    // 411k/s @48t on cold 1B targets).
    let mut jobs: Vec<(B256, Vec<Key>)> = Vec::new();
    for (acct, per) in storage_targets {
        if per.is_empty() {
            continue;
        }
        let mut slots: Vec<Key> = per.keys().map(|k| k.0).collect();
        slots.sort_unstable();
        let threads = proof_threads();
        let chunk = slots.len().div_ceil(threads).max(64);
        for c in slots.chunks(chunk) {
            jobs.push((*acct, c.to_vec()));
        }
    }
    let results: Vec<anyhow::Result<(B256, Vec<ProofTrieNodeV2>)>> = std::thread::scope(|s| {
        jobs.into_iter()
            .map(|(acct, slots)| {
                s.spawn(move || {
                    let nodes = match db.reveal_storage_paths(&acct.0, &slots)? {
                        Some(n) => to_v2_nodes(n)?,
                        None => vec![ProofTrieNodeV2 {
                            path: Nibbles::default(),
                            node: TrieNodeV2::EmptyRoot,
                            masks: None,
                        }],
                    };
                    Ok((acct, nodes))
                })
            })
            .collect::<Vec<_>>()
            .into_iter()
            .map(|h| h.join().expect("reveal thread panicked"))
            .collect()
    });
    let mut storage_proofs: B256Map<Vec<ProofTrieNodeV2>> = B256Map::default();
    for r in results {
        let (acct, nodes) = r?;
        storage_proofs.entry(acct).or_default().extend(nodes);
    }
    Ok(DecodedMultiProofV2 {
        account_proofs,
        storage_proofs,
    })
}

/// The generic proof walk (chunked, parallel), used under overlays or as
/// the fallback when the direct reveal cannot serve a target.
fn chunked_proofs(
    guard: &parking_lot::RwLockReadGuard<'_, FlatShadow>,
    overlay: Option<&(
        std::sync::Arc<TrieUpdatesSorted>,
        std::sync::Arc<HashedPostStateSorted>,
    )>,
    acct_targets: &B256Map<ProofV2TargetParent>,
    storage_targets: &B256Map<B256Map<ProofV2TargetParent>>,
) -> anyhow::Result<Vec<DecodedMultiProofV2>> {
    let n_storage: usize = storage_targets.values().map(|p| p.len()).sum();
    let mut flat: Vec<(B256, ProofV2Target)> = Vec::with_capacity(n_storage);
    for (acct, per) in storage_targets {
        for (k, m) in per {
            flat.push((*acct, ProofV2Target::new(*k).with_parent(*m)));
        }
    }
    flat.sort_unstable_by(|a, b| {
        a.0.cmp(&b.0)
            .then_with(|| a.1.key_nibbles.cmp(&b.1.key_nibbles))
    });
    // IO-latency-bound sync preads: oversubscribe past the core count
    // (measured near-linear to 48 threads). `TEMPO_FLATMPT_PROOF_THREADS`.
    let threads = proof_threads();
    let chunk_size = flat.len().div_ceil(threads).max(256);
    let mut chunks: Vec<MultiProofTargetsV2> = Vec::new();
    {
        let mut t = MultiProofTargetsV2::default();
        for (key, min_len) in acct_targets {
            t.account_targets
                .push(ProofV2Target::new(*key).with_parent(*min_len));
        }
        if !t.account_targets.is_empty() {
            chunks.push(t);
        }
    }
    for slice in flat.chunks(chunk_size) {
        let mut t = MultiProofTargetsV2::default();
        for (acct, target) in slice {
            t.storage_targets.entry(*acct).or_default().push(*target);
        }
        chunks.push(t);
    }

    let db = guard.db();
    std::thread::scope(|s| {
        let handles: Vec<_> = chunks
            .into_iter()
            .map(|t| {
                s.spawn(move || match overlay {
                    None => Proof::new(
                        FlatTrieCursorFactory { mpt: db },
                        FlatHashedCursorFactory { mpt: db },
                    )
                    .multiproof_v2(t),
                    Some((tu, hps)) => Proof::new(
                        InMemoryTrieCursorFactory::new(FlatTrieCursorFactory { mpt: db }, tu),
                        HashedPostStateCursorFactory::new(FlatHashedCursorFactory { mpt: db }, hps),
                    )
                    .multiproof_v2(t),
                })
            })
            .collect();
        handles
            .into_iter()
            .map(|h| h.join().expect("proof chunk thread panicked"))
            .collect::<Result<Vec<_>, _>>()
    })
    .map_err(|e| anyhow::anyhow!("multiproof_v2 over flat cursors: {e}"))
}

/// Parallelism for chunked proof fetches (`TEMPO_FLATMPT_PROOF_THREADS`).
fn proof_threads() -> usize {
    static N: std::sync::OnceLock<usize> = std::sync::OnceLock::new();
    *N.get_or_init(|| {
        std::env::var("TEMPO_FLATMPT_PROOF_THREADS")
            .ok()
            .and_then(|s| s.parse().ok())
            // In-node default: a small pool — reveals are fast enough at 8
            // threads (~65k targets/s) and execution must keep its cores
            // (48 reveal threads measurably starved the EVM: run43 12.5k tps
            // vs run44 17.7k with 8). Benches oversubscribe explicitly.
            .unwrap_or(8)
            .clamp(1, 128)
    })
}

enum Msg {
    State(revm::state::EvmState),
    Reveal(RevealBatch),
}

/// Path nodes captured by an execution-time state read (the read walks the
/// exact records a reveal needs — one fetch serves both consumers).
pub enum RevealBatch {
    Account {
        key: B256,
        nodes: Vec<mpt_flat_poc::reveal::RevealNode>,
    },
    Storage {
        account: B256,
        slot: B256,
        nodes: Vec<mpt_flat_poc::reveal::RevealNode>,
    },
}

/// Lossy handle for feeding execution-read reveals to the sparse worker.
/// Dropped batches only mean the worker fetches those paths itself.
#[derive(Clone)]
pub struct RevealSink {
    tx: mpsc::SyncSender<Msg>,
    dropped: std::sync::Arc<std::sync::atomic::AtomicU64>,
}

impl RevealSink {
    pub fn account(&self, key: B256, nodes: Vec<mpt_flat_poc::reveal::RevealNode>) {
        if self
            .tx
            .try_send(Msg::Reveal(RevealBatch::Account { key, nodes }))
            .is_err()
        {
            self.dropped
                .fetch_add(1, std::sync::atomic::Ordering::Relaxed);
        }
    }
    pub fn storage(&self, account: B256, slot: B256, nodes: Vec<mpt_flat_poc::reveal::RevealNode>) {
        if self
            .tx
            .try_send(Msg::Reveal(RevealBatch::Storage {
                account,
                slot,
                nodes,
            }))
            .is_err()
        {
            self.dropped
                .fetch_add(1, std::sync::atomic::Ordering::Relaxed);
        }
    }
}

/// Handle to an in-flight sparse commitment build. Dropping it (cancelled
/// payload) stops the worker; nothing shared was mutated.
pub struct SparseWorker {
    tx: Option<mpsc::SyncSender<Msg>>,
    /// Fast lane: `Finish` bypasses the (potentially hundreds of thousands
    /// deep) state/reveal queue — the builder blocks on the result, so queue
    /// wait here is block latency.
    finish_tx: mpsc::Sender<Vec<(Key, StateOp)>>,
    result_rx: mpsc::Receiver<anyhow::Result<(B256, SparseStats)>>,
    dropped: std::sync::Arc<std::sync::atomic::AtomicU64>,
}

impl SparseWorker {
    /// Spawn the commitment worker for a block whose parent state root is
    /// `parent_root`. Read-only against the shared shadow.
    pub fn begin(shadow: &'static RwLock<FlatShadow>, parent_root: B256) -> Self {
        let (tx, rx) = mpsc::sync_channel::<Msg>(65_536);
        let (finish_tx, finish_rx) = mpsc::channel::<Vec<(Key, StateOp)>>();
        let (result_tx, result_rx) = mpsc::channel();
        let dropped = std::sync::Arc::new(std::sync::atomic::AtomicU64::new(0));
        let dropped_w = dropped.clone();
        std::thread::Builder::new()
            .name("flatmpt-sparse".into())
            .spawn(move || {
                let mut w = Worker::new(shadow, parent_root);
                let mut finished = false;
                // Drain-then-pass: accumulate everything queued before deciding
                // to run a (multi-hundred-ms) proof pass, so passes cover big
                // batches and the channel rarely fills while one runs.
                'outer: loop {
                    // Fast lane first: a pending Finish must never wait behind
                    // the reveal/state backlog (the builder is blocked on it).
                    if let Ok(ops) = finish_rx.try_recv() {
                        w.stats.hook_dropped =
                            dropped_w.load(std::sync::atomic::Ordering::Relaxed);
                        let _ = result_tx.send(w.finish(ops));
                        finished = true;
                        break 'outer;
                    }
                    let first = match rx.recv_timeout(std::time::Duration::from_millis(2)) {
                        Ok(m) => m,
                        Err(mpsc::RecvTimeoutError::Timeout) => continue,
                        Err(mpsc::RecvTimeoutError::Disconnected) => {
                            // finish() sends the fast-lane message BEFORE
                            // dropping the main-channel sender: a Disconnected
                            // wake-up may carry a pending Finish — poll it or
                            // the worker dies with the result unsent.
                            if let Ok(ops) = finish_rx.try_recv() {
                                w.stats.hook_dropped =
                                    dropped_w.load(std::sync::atomic::Ordering::Relaxed);
                                let _ = result_tx.send(w.finish(ops));
                                finished = true;
                            }
                            break 'outer;
                        }
                    };
                    let mut msg = Some(first);
                    let mut in_batch = 0u32;
                    loop {
                        match msg.take() {
                            Some(Msg::State(state)) => w.on_state(state),
                            Some(Msg::Reveal(batch)) => w.on_reveal(batch),
                            None => break,
                        }
                        // Re-check the fast lane periodically inside deep drains.
                        in_batch += 1;
                        if in_batch.is_multiple_of(256) && let Ok(ops) = finish_rx.try_recv() {
                            w.stats.hook_dropped =
                                dropped_w.load(std::sync::atomic::Ordering::Relaxed);
                            let _ = result_tx.send(w.finish(ops));
                            finished = true;
                            break 'outer;
                        }
                        msg = rx.try_recv().ok();
                    }
                    if w.fresh >= PASS_TARGETS {
                        w.fresh = 0;
                        match w.reveal_pass(false) {
                            Ok(true) => w.stats.exec_passes += 1,
                            Ok(false) => w.stats.deferred_passes += 1,
                            Err(e) => {
                                tracing::warn!(target: "flatmpt", err = %format!("{e:#}"), "sparse exec pass failed");
                            }
                        }
                    }
                }
                if !finished {
                    // Channel closed without Finish: cancelled build. Repool
                    // the trie if it is still clean (reveals only) so the
                    // next build doesn't start blind — losing it here is what
                    // set up the r148 stale-reveal divergence.
                    let repooled = w.repool_cancelled();
                    tracing::debug!(target: "flatmpt", repooled, "sparse worker dropped (cancelled build)");
                }
            })
            .expect("spawn flatmpt-sparse");
        Self {
            tx: Some(tx),
            finish_tx,
            result_rx,
            dropped,
        }
    }

    /// State hook for the executor (prewarming only — final values come from
    /// the bundle passed to [`Self::finish`]). Lossy by design: if the worker
    /// is busy in a proof pass, batches are dropped rather than backpressuring
    /// execution — a missed prewarm only means the finish drain fetches it.
    pub fn hook(&self) -> impl revm::OnStateHook {
        let tx = self.tx.as_ref().expect("worker active").clone();
        let dropped = self.dropped.clone();
        move |state: revm::state::EvmState| {
            if tx.try_send(Msg::State(state)).is_err() {
                dropped.fetch_add(1, std::sync::atomic::Ordering::Relaxed);
            }
        }
    }

    /// Lossy handle for execution-read reveals (see [`RevealSink`]).
    pub fn reveal_sink(&self) -> RevealSink {
        RevealSink {
            tx: self.tx.as_ref().expect("worker active").clone(),
            dropped: self.dropped.clone(),
        }
    }

    /// Compute the state root for the block's net changes `ops` (hashed keys,
    /// as produced by [`crate::bundle_to_ops`]).
    pub fn finish(mut self, ops: Vec<(Key, StateOp)>) -> anyhow::Result<(B256, SparseStats)> {
        let tx = self.tx.take().expect("worker active");
        self.finish_tx
            .send(ops)
            .map_err(|_| anyhow::anyhow!("sparse worker died"))?;
        drop(tx);
        self.result_rx
            .recv()
            .map_err(|_| anyhow::anyhow!("sparse worker died without a result"))?
    }
}

struct Worker {
    shadow: &'static RwLock<FlatShadow>,
    parent_root: B256,
    /// Lock-free read snapshot of the flat store, refreshed opportunistically
    /// (try_read); reveals run against it and never wait behind the
    /// follower's write-locked applies. Sound for the pooled trie's blind
    /// regions (blinded ⇒ untouched since trie creation) iff the snapshot's
    /// stamp clears the trie's anchor; a fresh trie (pool miss) requires the
    /// snapshot to be exactly at the parent.
    snap: Option<mpt_flat_poc::FlatSnapshot>,
    snap_at_parent: bool,
    /// Apply sequence at which `snap` was captured (conservative: may lag).
    snap_seq: u64,
    /// Blind-region soundness anchor of `trie` (see [`Anchor`]).
    anchor: Anchor,
    /// True once any leaf update has been applied to the trie: the trie no
    /// longer represents plain parent state and must not be repooled on
    /// cancel. Reveals alone don't dirty it — they are parent-state facts.
    dirty: bool,
    trie: SparseStateTrie,
    account_updates: B256Map<LeafUpdate>,
    storage_updates: B256Map<B256Map<LeafUpdate>>,
    /// Proof targets already fetched → smallest min_len fetched (a request
    /// with a smaller min_len than previously fetched must be re-fetched).
    fetched_accounts: B256Map<ProofV2TargetParent>,
    fetched_storage: B256Map<B256Map<ProofV2TargetParent>>,
    /// Keys touched since the last reveal pass (pass trigger).
    fresh: usize,
    /// Slot values streamed from the state hook and handed to the trie
    /// (last write wins, mirroring the ops encoding exactly). Finish skips
    /// any op whose value matches — the hook already applied it — so at
    /// steady state the finish drain is only the hook's dropped batches.
    streamed_storage: B256Map<B256Map<Vec<u8>>>,
    stats: SparseStats,
}

impl Worker {
    fn new(shadow: &'static RwLock<FlatShadow>, parent_root: B256) -> Self {
        // Reuse the previous block's revealed trie when stacking directly on
        // its root — the steady-state case. Anything else (first block,
        // rebuild candidate, post-cancel) starts blind.
        let (mut trie, pool_hit, anchor) = match TRIE_POOL.lock().take() {
            Some((root, anchor, trie)) if root == parent_root => (trie, true, anchor),
            // Fresh trie: its blind regions are only pinned to the parent
            // state from here on, so arbitrary-lineage reveals are unsound
            // until the follower reaches this root (see `Anchor`).
            _ => (SparseStateTrie::new(), false, Anchor::Pending(parent_root)),
        };
        // Retain branch-node updates: finish() publishes them as the block's
        // overlay so descendants' proofs need not wait for the flat apply.
        trie.set_updates(true);
        let stats = SparseStats {
            pool_hit,
            ..Default::default()
        };
        Self {
            shadow,
            parent_root,
            snap: None,
            snap_at_parent: false,
            snap_seq: 0,
            anchor,
            dirty: false,
            trie,
            account_updates: B256Map::default(),
            storage_updates: B256Map::default(),
            fetched_accounts: B256Map::default(),
            fetched_storage: B256Map::default(),
            fresh: 0,
            streamed_storage: B256Map::default(),
            stats,
        }
    }

    /// Return the trie to the pool as representing `root`.
    fn pool_put(&mut self, root: B256) {
        let trie = std::mem::take(&mut self.trie);
        *TRIE_POOL.lock() = Some((root, self.anchor, trie));
    }

    /// A cancelled build's trie still represents plain parent state as long
    /// as no leaf update was applied (reveals are parent-state facts), so
    /// repool it instead of losing the warm trie — the r148 loss path: a
    /// build raced at flood end stole the trie, and its blind replacement
    /// went on to reveal from a stale snapshot. Never clobbers a newer entry.
    fn repool_cancelled(mut self) -> bool {
        if self.dirty {
            return false;
        }
        let mut pool = TRIE_POOL.lock();
        if pool.is_none() {
            *pool = Some((
                self.parent_root,
                self.anchor,
                std::mem::take(&mut self.trie),
            ));
            return true;
        }
        false
    }

    /// True iff the current snapshot is sound for this trie's blind regions:
    /// the follower reached the trie's creation root at some sequence the
    /// snapshot's stamp clears. Resolves a Pending anchor via the applied-
    /// roots ring (covers anchors passed while the trie was checked out).
    fn anchor_ok(&mut self) -> bool {
        if let Anchor::Pending(r) = self.anchor
            && let Some(s) = root_seq(r)
        {
            self.anchor = Anchor::Satisfied(s);
        }
        match self.anchor {
            Anchor::Satisfied(s) => self.snap_seq >= s,
            Anchor::Pending(_) => false,
        }
    }

    /// Execution-time streaming: apply touched slots as real `Changed` leaf
    /// updates (post-tx values, last write wins) so exec passes do the leaf
    /// walks while the EVM runs; account paths are prewarmed as `Touched`
    /// (their leaves need the storage root, encoded at promote). Values
    /// mirror the ops encoding exactly so finish can skip matching ops.
    /// Lossy by design: a dropped batch only means finish applies those ops.
    fn on_state(&mut self, state: revm::state::EvmState) {
        for (address, account) in &state {
            if !account.is_touched() {
                continue;
            }
            let acct = keccak256(address.as_slice());
            if !self.fetched_accounts.contains_key(&acct)
                && !self.account_updates.contains_key(&acct)
            {
                self.account_updates.insert(acct, LeafUpdate::Touched);
                self.fresh += 1;
            }
            if account.is_selfdestructed() {
                // Values streamed earlier for this account are stale; finish
                // removes a destroyed account's storage updates wholesale and
                // the skip-compare consults ops only, so no cleanup needed.
                continue;
            }
            for (slot, s) in &account.storage {
                if s.present_value == s.original_value {
                    continue;
                }
                let slot_key = keccak256(slot.to_be_bytes::<32>());
                let value = if s.present_value.is_zero() {
                    Vec::new()
                } else {
                    mpt_flat_poc::eth::storage_value_rlp(s.present_value)
                };
                let newly = !self
                    .storage_updates
                    .get(&acct)
                    .is_some_and(|u| u.contains_key(&slot_key))
                    && !self
                        .fetched_storage
                        .get(&acct)
                        .is_some_and(|f| f.contains_key(&slot_key));
                self.streamed_storage
                    .entry(acct)
                    .or_default()
                    .insert(slot_key, value.clone());
                self.storage_updates
                    .entry(acct)
                    .or_default()
                    .insert(slot_key, LeafUpdate::Changed(value));
                if newly {
                    self.fresh += 1;
                }
            }
        }
    }

    /// Drop storage tries that a failed reveal left blind (created by
    /// `reveal_decoded_multiproof_v2` before the per-trie reveal ran, then
    /// orphaned by its error). A blind trie in the map panics reth's
    /// `storage_trie_updates` unwrap at finish — this is the tolerance
    /// guarantee that a bad proof degrades to a refetch, never a dead worker.
    fn drop_blind_storage_tries(&mut self, accounts: impl Iterator<Item = B256>) {
        for acct in accounts {
            if let Some(t) = self.trie.take_storage_trie(&acct) {
                if matches!(t, reth_trie_sparse::RevealableSparseTrie::Revealed(_)) {
                    self.trie.insert_storage_trie(acct, t);
                } else {
                    tracing::warn!(
                        target: "flatmpt",
                        acct = %acct,
                        "dropped blind storage trie after failed reveal"
                    );
                }
            }
        }
    }

    /// Reveal path nodes captured by an execution-time read: the read already
    /// fetched the records, so the trie is revealed without its own fetch.
    /// Failures just leave the target for the normal fetch flow.
    fn on_reveal(&mut self, batch: RevealBatch) {
        match batch {
            RevealBatch::Account { key, nodes } => {
                if self.fetched_accounts.contains_key(&key) {
                    return;
                }
                let Ok(v2) = to_v2_nodes(nodes) else { return };
                let proof = DecodedMultiProofV2 {
                    account_proofs: v2,
                    storage_proofs: B256Map::default(),
                };
                if self.trie.reveal_decoded_multiproof_v2(proof).is_ok() {
                    self.fetched_accounts.insert(key, ProofV2TargetParent::NONE);
                }
            }
            RevealBatch::Storage {
                account,
                slot,
                nodes,
            } => {
                if self
                    .fetched_storage
                    .get(&account)
                    .is_some_and(|f| f.contains_key(&slot))
                {
                    return;
                }
                let Ok(v2) = to_v2_nodes(nodes) else { return };
                let mut storage_proofs: B256Map<Vec<ProofTrieNodeV2>> = B256Map::default();
                storage_proofs.insert(account, v2);
                let proof = DecodedMultiProofV2 {
                    account_proofs: Vec::new(),
                    storage_proofs,
                };
                if self.trie.reveal_decoded_multiproof_v2(proof).is_ok() {
                    self.fetched_storage
                        .entry(account)
                        .or_default()
                        .insert(slot, ProofV2TargetParent::NONE);
                } else {
                    self.drop_blind_storage_tries(std::iter::once(account));
                }
            }
        }
    }

    /// The authoritative finish: apply the bundle's net changes, drain all
    /// reveals, promote storage roots into account leaves, return the root.
    fn finish(&mut self, ops: Vec<(Key, StateOp)>) -> anyhow::Result<(B256, SparseStats)> {
        let t_finish = Instant::now();
        if ops.is_empty() {
            let parent = self.parent_root;
            self.pool_put(parent);
            return Ok((parent, self.stats));
        }
        let t_phase = Instant::now();
        // Net-change maps from the ops (ordered; SetAccount precedes its slot
        // ops, DeleteAccount precedes a recreate's SetAccount). Borrows `ops`:
        // the vec is handed to the async overlay build after the root.
        let mut pending_accounts: B256Map<Option<TrieAccount>> = B256Map::default();
        let mut destroyed: B256Set = B256Set::default();
        for (key, op) in &ops {
            let acct = B256::from(*key);
            self.account_updates
                .entry(acct)
                .or_insert(LeafUpdate::Touched);
            match op {
                StateOp::SetAccount {
                    nonce,
                    balance,
                    code_hash,
                } => {
                    pending_accounts.insert(
                        acct,
                        Some(TrieAccount {
                            nonce: *nonce,
                            balance: *balance,
                            storage_root: EMPTY_ROOT_HASH, // patched at promote
                            code_hash: B256::from(*code_hash),
                        }),
                    );
                }
                StateOp::DeleteAccount => {
                    destroyed.insert(acct);
                    pending_accounts.insert(acct, None);
                }
                StateOp::SetStorage { slot, value } => {
                    let slot = B256::from(*slot);
                    // Skip ops the hook already streamed with this exact
                    // value: the leaf is either applied or pending with the
                    // right value — either way the drain need not redo it.
                    if self
                        .streamed_storage
                        .get(&acct)
                        .and_then(|s| s.get(&slot))
                        .is_some_and(|v| v == value)
                    {
                        continue;
                    }
                    self.storage_updates
                        .entry(acct)
                        .or_default()
                        .insert(slot, LeafUpdate::Changed(value.clone()));
                }
                StateOp::DeleteStorage { slot } => {
                    let slot = B256::from(*slot);
                    if self
                        .streamed_storage
                        .get(&acct)
                        .and_then(|s| s.get(&slot))
                        .is_some_and(|v| v.is_empty())
                    {
                        continue;
                    }
                    self.storage_updates
                        .entry(acct)
                        .or_default()
                        .insert(slot, LeafUpdate::Changed(Vec::new()));
                }
                StateOp::WipeStorage => {
                    // Wiping under already-revealed storage nodes is the same
                    // hazard as destroy+recreate — punt to root_for.
                    anyhow::bail!("WipeStorage op: sparse path unsupported");
                }
            }
        }
        // Destroy-then-recreate with fresh storage would need the old storage
        // trie wiped from under already-revealed nodes — punt to root_for.
        for acct in &destroyed {
            if pending_accounts.get(acct).is_some_and(|a| a.is_some())
                && self
                    .storage_updates
                    .get(acct)
                    .is_some_and(|u| !u.is_empty())
            {
                anyhow::bail!("destroyed+recreated account with storage: sparse path unsupported");
            }
            // Storage of a plainly destroyed account is irrelevant once the
            // account leaf is removed; drop any leftover Touched entries.
            if pending_accounts.get(acct) == Some(&None) {
                self.storage_updates.remove(acct);
            }
        }

        // Drain storage updates and pre-reveal account paths (needed both for
        // old storage roots and for the account leaf writes below). No
        // up-front flat-at-parent wait: with a warm pool most blocks need no
        // proof fetches at all, and gating the hot path on the background
        // follower here turns a transient apply lag into a cadence spiral
        // (run34: wait_parent 61→1610ms while proof_ms stayed 0). The fetch
        // path inside reveal_pass waits iff a proof is actually needed.
        self.stats.fin_netmap_ms = t_phase.elapsed().as_millis() as u64;
        let t_wait = Instant::now();
        if !self.reveal_pass(true)? {
            anyhow::bail!("finish reveal pass deferred despite wait");
        }
        self.stats.wait_parent_ms = t_wait.elapsed().as_millis() as u64;
        self.stats.fin_drain_ms = self.stats.wait_parent_ms;

        // Promote: encode every changed account leaf with its storage root.
        // Storage roots that need hashing (accounts whose storage tries live
        // in this trie) go first — `storage_root` needs `&mut`. The bulk —
        // tens of thousands of EOA leaves whose storage root comes from the
        // stored leaf (read-only walk + decode + encode) — fans out across
        // threads; the serial version was the largest finish phase (~28ms of
        // 67 at 110k ops).
        let t_phase = Instant::now();
        // Accounts whose storage changed without an account op still need
        // their leaf re-encoded with the new storage root. Execution-derived
        // ops always pair storage changes with a SetAccount, so this is a
        // no-op live — but replayed or synthetic ops may not, and silently
        // keeping the old storage root poisons the account trie. The drain
        // above revealed these leaves (their `Touched` updates), so the
        // stored value is available here.
        let storage_touched: Vec<B256> = self
            .storage_updates
            .keys()
            .chain(self.streamed_storage.keys())
            .copied()
            .collect();
        for acct in storage_touched {
            if !pending_accounts.contains_key(&acct) && !destroyed.contains(&acct) {
                let value = self.trie.get_account_value(&acct).ok_or_else(|| {
                    anyhow::anyhow!("storage-changed account {acct} not revealed at promote")
                })?;
                let account = TrieAccount::decode(&mut value.as_slice())
                    .map_err(|e| anyhow::anyhow!("stored account rlp: {e}"))?;
                pending_accounts.insert(acct, Some(account));
            }
        }
        let t_sroot = Instant::now();
        let mut hashed_sroots: B256Map<B256> = B256Map::default();
        for (acct, account) in &pending_accounts {
            if account.is_some()
                && !destroyed.contains(acct)
                && (self.fetched_storage.contains_key(acct)
                    || self.trie.storage_trie_ref(acct).is_some())
            {
                let r = self
                    .trie
                    .storage_root(acct, TrieNodeEpoch::new(self.snap_seq.saturating_add(1)))
                    .ok_or_else(|| anyhow::anyhow!("storage root unavailable for {acct}"))?;
                hashed_sroots.insert(*acct, r);
            }
        }
        self.stats.fin_sroot_ms = t_sroot.elapsed().as_millis() as u64;

        let entries: Vec<(B256, Option<TrieAccount>)> = pending_accounts.into_iter().collect();
        let trie = &self.trie;
        let destroyed_ref = &destroyed;
        let sroots_ref = &hashed_sroots;
        let encode_chunk =
            |chunk: &[(B256, Option<TrieAccount>)]| -> anyhow::Result<Vec<(B256, Vec<u8>)>> {
                let mut out = Vec::with_capacity(chunk.len());
                for (acct, account) in chunk {
                    let Some(account) = account else {
                        out.push((*acct, Vec::new()));
                        continue;
                    };
                    let mut account = *account;
                    account.storage_root = if destroyed_ref.contains(acct) {
                        EMPTY_ROOT_HASH
                    } else if let Some(r) = sroots_ref.get(acct) {
                        *r
                    } else if let Some(value) = trie.get_account_value(acct) {
                        TrieAccount::decode(&mut value.as_slice())
                            .map_err(|e| anyhow::anyhow!("stored account rlp: {e}"))?
                            .storage_root
                    } else {
                        EMPTY_ROOT_HASH
                    };
                    let mut buf = Vec::with_capacity(128);
                    account.encode(&mut buf);
                    out.push((*acct, buf));
                }
                Ok(out)
            };
        let threads = std::thread::available_parallelism()
            .map(|n| n.get().min(8))
            .unwrap_or(4);
        let encoded: Vec<(B256, Vec<u8>)> = if entries.len() >= 2048 && threads > 1 {
            let chunk = entries.len().div_ceil(threads);
            std::thread::scope(|sc| {
                entries
                    .chunks(chunk)
                    .map(|c| sc.spawn(move || encode_chunk(c)))
                    .collect::<Vec<_>>()
                    .into_iter()
                    .map(|h| h.join().expect("promote chunk panicked"))
                    .collect::<anyhow::Result<Vec<_>>>()
            })?
            .into_iter()
            .flatten()
            .collect()
        } else {
            encode_chunk(&entries)?
        };
        for (acct, buf) in encoded {
            self.account_updates.insert(acct, LeafUpdate::Changed(buf));
        }

        self.stats.fin_promote_ms = t_phase.elapsed().as_millis() as u64;

        // Final account-trie drain (paths are pre-revealed; deletions may
        // still pull sibling reveals) and the root.
        let t_phase = Instant::now();
        if !self.reveal_pass(true)? {
            anyhow::bail!("final reveal pass deferred despite wait");
        }
        // Last line of defense: any storage trie still blind here would panic
        // reth's storage_trie_updates inside root_with_updates. Reaching this
        // point with one is sound to drop: a blind trie with pending updates
        // would have stalled the drain above, so a blind survivor carries no
        // updates and its account leaf took the stored storage root.
        let touched: Vec<B256> = self
            .fetched_storage
            .keys()
            .chain(self.streamed_storage.keys())
            .copied()
            .collect();
        self.drop_blind_storage_tries(touched.into_iter());
        let (root, trie_updates) = self
            .trie
            .root_with_updates(TrieNodeEpoch::new(self.snap_seq.saturating_add(1)))
            .map_err(|e| anyhow::anyhow!("sparse root: {e}"))?;
        self.stats.fin_root_ms = t_phase.elapsed().as_millis() as u64;
        // Overlay build (post-state from ops + sorted trie updates) is only
        // needed by proof fetches of descendant blocks, which at warm state
        // are rare and, when they race this thread, fall back to the safe
        // wait-for-parent path — so it leaves the critical path entirely.
        let t_phase = Instant::now();
        let slot = push_overlay_pending(self.parent_root, root);
        std::thread::Builder::new()
            .name("flatmpt-overlay".into())
            .spawn(move || {
                let built = (trie_updates.into_sorted(), ops_to_post_state(&ops));
                *slot.write() = Some(built);
            })
            .map_err(|e| anyhow::anyhow!("spawn overlay build: {e}"))?;
        self.stats.fin_overlay_ms = t_phase.elapsed().as_millis() as u64;
        self.pool_put(root);
        self.stats.finish_ms = t_finish.elapsed().as_millis() as u64;
        Ok((root, self.stats))
    }

    /// Refresh the read snapshot if the writer isn't busy; keep the old one
    /// otherwise (stale snapshots stay sound when the anchor clears them).
    /// Falls back to the cross-block snapshot pool before ever blocking.
    fn refresh_snap(&mut self, block: bool) {
        let guard = if block {
            Some(self.shadow.read())
        } else {
            self.shadow.try_read()
        };
        if let Some(g) = guard {
            self.snap_at_parent = g.at_parent(self.parent_root);
            self.snap_seq = APPLY_SEQ.load(std::sync::atomic::Ordering::SeqCst);
            // A snapshot AT the parent is ground truth for every target, so
            // it also satisfies a pending anchor for all later snapshots:
            // paths still blind then were untouched by every build since
            // creation, hence identical from here on. This is the anchor's
            // only satisfaction path when the creation root never shows up
            // in the follower's applied roots (e.g. the golden-genesis
            // header-root escape).
            if self.snap_at_parent && matches!(self.anchor, Anchor::Pending(_)) {
                self.anchor = Anchor::Satisfied(self.snap_seq);
            }
            let snap = g.db().snapshot();
            *SNAP_POOL.lock() = Some((snap.clone(), self.snap_seq));
            self.snap = Some(snap);
        } else if self.snap.is_none() {
            if let Some((snap, seq)) = SNAP_POOL.lock().clone() {
                self.snap = Some(snap);
                self.snap_seq = seq;
            }
            self.snap_at_parent = false;
        }
    }

    /// One reveal pass: run `update_leaves` over all pending maps, fetch a
    /// multiproof over the flat cursors for any blinded targets, reveal, and
    /// retry until drained. Returns Ok(false) if deferred because the flat
    /// store isn't at the parent (only when `must_complete` is false).
    fn reveal_pass(&mut self, must_complete: bool) -> anyhow::Result<bool> {
        let mut stall_rounds = 0u32;
        loop {
            // Raw targets with the trie's requested min_len. A key already
            // fetched at min_len M is fresh again iff re-requested with a
            // smaller min_len (deeper structure got exposed) — reth's own
            // dedup rule.
            let mut acct_targets: B256Map<ProofV2TargetParent> = B256Map::default();
            let mut storage_targets: B256Map<B256Map<ProofV2TargetParent>> = B256Map::default();

            // Value-bearing updates are about to hit the trie: it stops
            // being plain parent state (Touched prewarms only reveal).
            if !self.dirty
                && (self.storage_updates.values().any(|u| !u.is_empty())
                    || self
                        .account_updates
                        .values()
                        .any(|u| matches!(u, LeafUpdate::Changed(_))))
            {
                self.dirty = true;
            }

            for (acct, updates) in self.storage_updates.iter_mut() {
                if updates.is_empty() {
                    continue;
                }
                let trie = self.trie.get_or_create_storage_trie_mut(*acct);
                let per = storage_targets.entry(*acct).or_default();
                trie.update_leaves(updates, |key, min_len| {
                    per.entry(key)
                        .and_modify(|m| *m = (*m).min(min_len))
                        .or_insert(min_len);
                })
                .map_err(|e| anyhow::anyhow!("storage update_leaves: {e}"))?;
            }
            storage_targets.retain(|_, per| !per.is_empty());
            self.trie
                .trie_mut()
                .update_leaves(&mut self.account_updates, |key, min_len| {
                    acct_targets
                        .entry(key)
                        .and_modify(|m| *m = (*m).min(min_len))
                        .or_insert(min_len);
                })
                .map_err(|e| anyhow::anyhow!("account update_leaves: {e}"))?;

            let drained = self.account_updates.is_empty()
                && self.storage_updates.values().all(|u| u.is_empty());
            if drained {
                return Ok(true);
            }

            let fresh = acct_targets
                .iter()
                .any(|(k, m)| self.fetched_accounts.get(k).is_none_or(|prev| *m < *prev))
                || storage_targets.iter().any(|(a, per)| {
                    per.iter().any(|(k, m)| {
                        self.fetched_storage
                            .get(a)
                            .and_then(|f| f.get(k))
                            .is_none_or(|prev| *m < *prev)
                    })
                });
            if fresh {
                stall_rounds = 0;
            } else {
                stall_rounds += 1;
                if acct_targets.is_empty() && storage_targets.is_empty() {
                    let pending: usize = self.account_updates.len()
                        + self
                            .storage_updates
                            .values()
                            .map(|u| u.len())
                            .sum::<usize>();
                    anyhow::bail!(
                        "sparse reveal stalled with {pending} pending updates and no targets"
                    );
                }
                if stall_rounds > STALL_RETRIES {
                    anyhow::bail!(
                        "sparse reveal stalled after {STALL_RETRIES} refetches; sample targets: {:?} / {:?}",
                        acct_targets.iter().next(),
                        storage_targets
                            .iter()
                            .find_map(|(a, per)| per.iter().next().map(|(k, m)| (*a, *k, *m))),
                    );
                }
                tracing::info!(
                    target: "flatmpt",
                    round = stall_rounds,
                    accounts = acct_targets.len(),
                    slots = storage_targets.values().map(|p| p.len()).sum::<usize>(),
                    "sparse reveal refetching still-blinded targets"
                );
            }

            // Fetch under one read guard: the parent check and the proof walks
            // must see the same flat snapshot. Native V2 proofs — the v1→v2
            // conversion silently drops extension nodes with unrevealed
            // children, which permanently stalls exclusion-proof inserts.
            //
            // Proof generation is the dominant hot-path cost (a tempo block
            // can carry 100k+ storage targets in one contract), so targets
            // are split into path-contiguous chunks proved on parallel
            // threads over the same snapshot — reth's proof-worker chunking,
            // inlined. Reveal stays sequential (it is ~1% of proof time).
            let t_proof = Instant::now();
            let n_acct = acct_targets.len() as u64;
            let n_storage = storage_targets.values().map(|p| p.len()).sum::<usize>() as u64;
            if must_complete && n_acct + n_storage > 0 {
                // Ceiling diagnostic: what does the finish drain still fetch
                // despite execution-read reveals? Sample the targets.
                let sample_a: Vec<_> = acct_targets.keys().take(3).collect();
                let sample_s: Vec<_> = storage_targets
                    .iter()
                    .flat_map(|(a, per)| per.keys().take(2).map(move |k| (*a, *k)))
                    .take(4)
                    .collect();
                tracing::info!(
                    target: "flatmpt",
                    n_acct,
                    n_storage,
                    ?sample_a,
                    ?sample_s,
                    "finish drain targets"
                );
            }
            // Lock-free fast path first: refresh the snapshot if the writer
            // is idle, and reveal from it without ever waiting on the lock.
            // Sound iff the snapshot is at the parent (ground truth), or the
            // trie carried over AND the snapshot is no older than the trie's
            // creation state (blind ⇒ untouched since creation — NOT since
            // forever: a freshly recreated trie is blind on paths the
            // preceding blocks touched, and a lagging snapshot serves their
            // pre-update content).
            let mut direct: Option<DecodedMultiProofV2> = None;
            if fast_reveal() {
                self.refresh_snap(false);
                let mut sound = self.snap_at_parent || (self.stats.pool_hit && self.anchor_ok());
                if self.snap.is_none() || !sound {
                    self.refresh_snap(true);
                    sound = self.snap_at_parent || (self.stats.pool_hit && self.anchor_ok());
                }
                if let Some(snap) = &self.snap
                    && sound
                {
                    match direct_reveal(snap, &acct_targets, &storage_targets) {
                        Ok(p) => direct = Some(p),
                        Err(e)
                            if std::env::var("TEMPO_FLATMPT_NO_PROOF_FALLBACK").as_deref()
                                == Ok("1") =>
                        {
                            return Err(anyhow::anyhow!("direct reveal failed (strict): {e:#}"));
                        }
                        Err(e) => {
                            tracing::warn!(
                                target: "flatmpt",
                                err = %format!("{e:#}"),
                                "direct reveal failed; using proof walk"
                            );
                        }
                    }
                }
            }
            let proofs = if let Some(p) = direct {
                vec![p]
            } else {
                let guard = self.shadow.read();
                // Fast path: flat is at the parent. Otherwise proofs run
                // against flat-at-its-current-root plus the overlay stack of
                // the intervening un-applied blocks; only an unknown lineage
                // (deep lag, rebuild race) still waits for the follower.
                let overlay = if guard.at_parent(self.parent_root) {
                    None
                } else if let Some(chain) = overlay_chain(guard.current_root(), self.parent_root) {
                    Some(chain)
                } else {
                    if !must_complete {
                        return Ok(false);
                    }
                    drop(guard);
                    self.wait_for_parent()?;
                    continue;
                };

                chunked_proofs(&guard, overlay.as_ref(), &acct_targets, &storage_targets)?
            };
            self.stats.proof_ms += t_proof.elapsed().as_millis() as u64;

            let t_reveal = Instant::now();
            for mut proof in proofs {
                // An empty storage node list can't reveal a blind trie, but it
                // means "empty trie" — normalize (belt-and-braces for every
                // proof producer; the engine walker normalizes at source).
                for nodes in proof.storage_proofs.values_mut() {
                    if nodes.is_empty() {
                        nodes.push(ProofTrieNodeV2 {
                            path: Nibbles::default(),
                            node: TrieNodeV2::EmptyRoot,
                            masks: None,
                        });
                    }
                }
                let accts: Vec<B256> = proof.storage_proofs.keys().copied().collect();
                // Cheap shape summary, kept for the failure diagnostic: the
                // first node's path depth per trie (a rootless proof — first
                // path non-empty on a blind trie — is the classic Blind).
                let acct_first = proof.account_proofs.first().map(|p| p.path.len());
                let stor_first: Vec<(B256, Option<usize>)> = proof
                    .storage_proofs
                    .iter()
                    .map(|(a, n)| (*a, n.first().map(|p| p.path.len())))
                    .collect();
                if let Err(e) = self.trie.reveal_decoded_multiproof_v2(proof) {
                    tracing::warn!(
                        target: "flatmpt",
                        err = %e,
                        ?acct_first,
                        storage_first_paths = ?stor_first,
                        "reveal failed — proof shape"
                    );
                    // A failed reveal can leave freshly-created storage tries
                    // blind; a blind trie PANICS reth's storage_trie_updates
                    // at finish. Drop them — the targets stay pending and go
                    // through the next fetch round.
                    self.drop_blind_storage_tries(accts.iter().copied());
                    return Err(anyhow::anyhow!("reveal_decoded_multiproof_v2: {e}"));
                }
            }
            self.stats.reveal_ms += t_reveal.elapsed().as_millis() as u64;
            self.stats.account_targets += n_acct;
            self.stats.storage_targets += n_storage;
            for (key, min_len) in acct_targets {
                self.fetched_accounts
                    .entry(key)
                    .and_modify(|m| *m = (*m).min(min_len))
                    .or_insert(min_len);
            }
            for (acct, per) in storage_targets {
                let f = self.fetched_storage.entry(acct).or_default();
                for (k, m) in per {
                    f.entry(k)
                        .and_modify(|prev| *prev = (*prev).min(m))
                        .or_insert(m);
                }
            }
            if must_complete {
                self.stats.finish_rounds += 1;
            }
        }
    }

    /// Block until the flat store is at this block's parent, nudging the
    /// follower to unwind an abandoned candidate if one is applied.
    #[allow(clippy::result_large_err)]
    fn wait_for_parent(&self) -> anyhow::Result<()> {
        let deadline = Instant::now() + parent_wait();
        let mut requested = false;
        loop {
            if self.shadow.read().at_parent(self.parent_root) {
                return Ok(());
            }
            if !requested {
                crate::follower::request_parent(self.parent_root);
                requested = true;
            }
            if Instant::now() >= deadline {
                anyhow::bail!(
                    "flat store did not reach parent root {} within {:?}",
                    self.parent_root,
                    parent_wait()
                );
            }
            std::thread::sleep(Duration::from_millis(2));
        }
    }
}

#[cfg(test)]
pub(super) mod tests {
    use super::*;
    use crate::FlatShadow;
    use alloy_primitives::U256;
    use mpt_flat_poc::{
        FlatMpt,
        eth::{EMPTY_CODE_HASH, storage_value_rlp},
    };

    pub(super) fn akey(b: u8) -> Key {
        keccak256([b; 20]).0
    }

    /// Clear the process-wide worker statics on entry and exit: tests that
    /// pollute TRIE_POOL / SNAP_POOL / OVERLAYS (cross-block carry) would
    /// otherwise poison concurrently-running worker tests.
    pub(super) fn worker_statics_guard() -> impl Drop {
        static LOCK: parking_lot::Mutex<()> = parking_lot::Mutex::new(());
        fn clear() {
            *super::TRIE_POOL.lock() = None;
            *super::SNAP_POOL.lock() = None;
            super::OVERLAYS.lock().clear();
            super::RECENT_ROOTS.lock().clear();
        }
        struct G(#[allow(dead_code)] parking_lot::MutexGuard<'static, ()>);
        impl Drop for G {
            fn drop(&mut self) {
                clear();
            }
        }
        let g = LOCK.lock();
        clear();
        G(g)
    }

    pub(super) fn set_acct(b: u8, nonce: u64) -> (Key, StateOp) {
        (
            akey(b),
            StateOp::SetAccount {
                nonce,
                balance: U256::from(1_000u64) + U256::from(nonce),
                code_hash: EMPTY_CODE_HASH.0,
            },
        )
    }

    pub(super) fn set_slot(b: u8, slot: u16, v: u64) -> (Key, StateOp) {
        let slot_key = keccak256(U256::from(slot).to_be_bytes::<32>()).0;
        (
            akey(b),
            StateOp::SetStorage {
                slot: slot_key,
                value: storage_value_rlp(U256::from(v)),
            },
        )
    }

    pub(super) fn del_slot(b: u8, slot: u16) -> (Key, StateOp) {
        let slot_key = keccak256(U256::from(slot).to_be_bytes::<32>()).0;
        (akey(b), StateOp::DeleteStorage { slot: slot_key })
    }

    /// THE Phase-2 gate: the sparse-over-flat commitment must reproduce the
    /// flat engine's own root for blocks covering every supported op shape —
    /// including a second block whose proofs walk the post-block-1 flat state.
    #[test]
    fn sparse_commitment_matches_flat_apply() {
        let _guard = worker_statics_guard();
        let dir = tempfile::tempdir().unwrap();
        let path = dir.path().join("sparse-gate.flat");
        let path = path.to_str().unwrap();

        // Genesis: 200 plain accounts; #1 with 3 slots, #2 with 300 slots
        // (deep storage trie), #3 with a single slot.
        let mut genesis: Vec<(Key, StateOp)> = (0..200u8).map(|i| set_acct(i, 1)).collect();
        for s in 0..3u16 {
            genesis.push(set_slot(1, s, 7 + s as u64));
        }
        for s in 0..300u16 {
            genesis.push(set_slot(2, s, 1 + s as u64));
        }
        genesis.push(set_slot(3, 0, 42));

        let mut oracle =
            FlatMpt::create(format!("{path}.oracle"), mpt_flat_poc::Config::default()).unwrap();
        let (genesis_root, _) = oracle.apply_block(genesis.clone()).unwrap();
        drop(oracle);
        let g = B256::from(genesis_root);

        let s = FlatShadow::init(path, genesis, g).unwrap();
        let shadow: &'static RwLock<FlatShadow> = Box::leak(Box::new(RwLock::new(s)));

        // Block 1: info change, new account, plain delete, storage-heavy
        // delete, slot update + insert + delete, storage cleared to empty.
        let ops1: Vec<(Key, StateOp)> = vec![
            set_acct(5, 99),
            set_acct(201, 1),
            (akey(9), StateOp::DeleteAccount),
            (akey(2), StateOp::DeleteAccount),
            set_acct(1, 2),
            set_slot(1, 0, 777),
            set_slot(1, 400, 5),
            del_slot(1, 1),
            set_acct(3, 2),
            del_slot(3, 0),
        ];

        let mut w = Worker::new(shadow, g);
        let (sparse1, stats1) = w.finish(ops1.clone()).unwrap();
        let flat1 = shadow.write().root_for(0, g, ops1).unwrap();
        assert_eq!(sparse1, flat1, "block 1 sparse vs flat root");
        assert!(stats1.account_targets > 0 && stats1.storage_targets > 0);

        // Block 2 on top of block 1: proofs now walk the advanced flat state;
        // recreate a previously deleted account; touch the deep account's
        // neighbours.
        let ops2: Vec<(Key, StateOp)> = vec![
            set_acct(9, 3),
            set_acct(7, 5),
            set_acct(1, 3),
            set_slot(1, 400, 6),
            set_slot(1, 401, 9),
        ];
        let mut w2 = Worker::new(shadow, sparse1);
        let (sparse2, _) = w2.finish(ops2.clone()).unwrap();
        let flat2 = shadow.write().root_for(1, sparse1, ops2).unwrap();
        assert_eq!(sparse2, flat2, "block 2 sparse vs flat root");
        assert_ne!(sparse1, sparse2);

        // Empty block: parent root passes through.
        let mut w3 = Worker::new(shadow, sparse2);
        let (sparse3, _) = w3.finish(Vec::new()).unwrap();
        assert_eq!(sparse3, sparse2);
    }
}

#[cfg(test)]
mod stall_tests {
    use super::{tests::*, *};
    use crate::FlatShadow;
    use mpt_flat_poc::FlatMpt;

    /// TEMP diagnostic: dump the storage proof for a stalled slot.
    #[test]
    fn diag_promoted_storage_proof() {
        let dir = tempfile::tempdir().unwrap();
        let path = dir.path().join("diag.flat");
        let path = path.to_str().unwrap();

        let mut genesis: Vec<(Key, StateOp)> = vec![set_acct(200, 1)];
        for s in 0..50_000u16 {
            genesis.push(set_slot(200, s, 5 + s as u64));
        }
        let mut oracle =
            FlatMpt::create(format!("{path}.oracle"), mpt_flat_poc::Config::default()).unwrap();
        let (genesis_root, _) = oracle.apply_block(genesis.clone()).unwrap();
        drop(oracle);
        let g = B256::from(genesis_root);
        let s = FlatShadow::init(path, genesis, g).unwrap();
        let shadow: &'static RwLock<FlatShadow> = Box::leak(Box::new(RwLock::new(s)));

        let acct = B256::from(akey(200));
        // a NONEXISTENT slot (exclusion proof — the stalling insert shape)
        let slot_key = B256::from(keccak256(
            alloy_primitives::U256::from(60_000u64).to_be_bytes::<32>(),
        ));

        let guard = shadow.read();
        let tf = crate::cursors::FlatTrieCursorFactory { mpt: guard.db() };
        let hf = crate::cursors::FlatHashedCursorFactory { mpt: guard.db() };
        let mut targets = reth_trie::MultiProofTargets::default();
        let mut slot_keys: Vec<B256> = (0..100u64)
            .map(|i| {
                B256::from(keccak256(
                    alloy_primitives::U256::from(50_000 + i).to_be_bytes::<32>(),
                ))
            })
            .collect();
        slot_keys.push(slot_key);
        for k in &slot_keys {
            targets.entry(acct).or_default().insert(*k);
        }
        let proof = Proof::new(tf, hf).multiproof(targets).unwrap();

        eprintln!("account subtree nodes:");
        for p in proof.account_subtree.keys() {
            eprintln!("  acct node path len={} {:?}", p.len(), p);
        }
        for (a, sp) in proof.storages.iter() {
            eprintln!(
                "storage {a}: root={} subtree={} nodes",
                sp.root,
                sp.subtree.iter().count()
            );
            let mut paths: Vec<_> = sp.subtree.keys().collect();
            paths.sort();
            for p in paths.iter() {
                let d = format!("{p:?}");
                if d.contains("(0x55") || d.contains("(0x5)") {
                    eprintln!("  st node path len={:2} {:?}", p.len(), p);
                }
            }
        }
        eprintln!("slot nibbles: {:?}", reth_trie::Nibbles::unpack(slot_key));

        // Dump our cursor's branch entry at 0x5500 and neighbours.
        {
            use reth_trie::trie_cursor::{TrieCursor as _, TrieCursorFactory as _};
            let mut c = tf.storage_trie_cursor(acct).unwrap();
            let mut path = reth_trie::Nibbles::default();
            for n in [5u8, 5, 0, 0] {
                path.push(n);
            }
            let e = c.seek(path).unwrap();
            if let Some((p, node)) = e {
                eprintln!(
                    "cursor@{p:?}: state={:016b} tree={:016b} hash={:016b} nhashes={}",
                    node.state_mask.get(),
                    node.tree_mask.get(),
                    node.hash_mask.get(),
                    node.hashes.len()
                );
            } else {
                eprintln!("cursor@0x5500: NONE");
            }
            // next branch after 0x5500
            if let Some((p, node)) = c.next().unwrap() {
                eprintln!(
                    "next branch: {p:?} state={:016b} tree={:016b} hash={:016b}",
                    node.state_mask.get(),
                    node.tree_mask.get(),
                    node.hash_mask.get()
                );
            } else {
                eprintln!("next branch: NONE");
            }
            // leaves under 0x55009
            use reth_trie::hashed_cursor::{HashedCursor as _, HashedCursorFactory as _};
            let mut hc = hf.hashed_storage_cursor(acct).unwrap();
            let mut seek = [0u8; 32];
            seek[0] = 0x55;
            seek[1] = 0x00;
            seek[2] = 0x90;
            let mut cur = hc.seek(B256::from(seek)).unwrap();
            for _ in 0..3 {
                match cur {
                    Some((k, _)) => {
                        eprintln!("leaf: {k}");
                        cur = hc.next().unwrap();
                    }
                    None => {
                        eprintln!("leaf: NONE");
                        break;
                    }
                }
            }
        }

        // What does the decoded proof hold at 0x5500?
        {
            let decoded: reth_trie::DecodedMultiProof = proof.clone().try_into().unwrap();
            let sp = decoded.storages.get(&acct).unwrap();
            for (p, n) in sp.subtree.iter() {
                if p.len() == 4 && format!("{p:?}").contains("0x5500") {
                    eprintln!("decoded@{p:?}: {n:?}");
                }
                if p.len() == 5 && format!("{p:?}").contains("0x55001") {
                    eprintln!("decoded@{p:?}: {n:?}");
                }
            }
        }
        // Now feed it to a fresh sparse trie and try the update.
        let mut trie = SparseStateTrie::new();
        trie.reveal_multiproof(proof).unwrap();
        let st = trie.get_or_create_storage_trie_mut(acct);
        let mut updates = B256Map::default();
        for k in &slot_keys {
            updates.insert(*k, LeafUpdate::Changed(vec![0x01]));
        }
        let mut asked: Vec<(B256, ProofV2TargetParent)> = Vec::new();
        st.update_leaves(&mut updates, |k, m| asked.push((k, m)))
            .unwrap();
        asked.sort();
        eprintln!(
            "still pending: {} asked(first 5): {:?}",
            updates.len(),
            &asked[..asked.len().min(5)]
        );
        for (k, _) in asked.iter().take(3) {
            eprintln!("pending key nibbles: {:?}", reth_trie::Nibbles::unpack(*k));
        }
        drop(guard);

        // Subset bisection: which op kind stalls with a fresh worker?
        for (name, ops) in [
            (
                "updates-8",
                (0..8u16)
                    .map(|s| set_slot(200, s * 100, 9_000 + s as u64))
                    .collect::<Vec<_>>(),
            ),
            (
                "updates-400",
                (0..400u16)
                    .map(|s| set_slot(200, s * 100, 9_000 + s as u64))
                    .collect(),
            ),
            (
                "deletes-100",
                (0..100u16).map(|s| del_slot(200, 7 + s * 250)).collect(),
            ),
            (
                "inserts-100",
                (0..100u16).map(|s| set_slot(200, 50_000 + s, 3)).collect(),
            ),
        ] {
            let mut all = vec![set_acct(200, 2)];
            all.extend(ops);
            let mut w = Worker::new(shadow, g);
            match w.finish(all) {
                Ok((root, st)) => eprintln!(
                    "subset {name}: OK root={root} targets={} rounds={}",
                    st.storage_targets, st.finish_rounds
                ),
                Err(e) => eprintln!("subset {name}: FAIL {e:#}"),
            }
        }
    }

    /// A promoted account (storage >16KB lifts into the RAM frontier as
    /// PromotedAccount): proofs over its storage trie must still reveal —
    /// the live-bench stall was isolated to the giant TIP20 contract.
    #[test]
    fn sparse_over_promoted_account_storage() {
        let _guard = worker_statics_guard();
        let dir = tempfile::tempdir().unwrap();
        let path = dir.path().join("promoted.flat");
        let path = path.to_str().unwrap();

        let mut genesis: Vec<(Key, StateOp)> = vec![set_acct(200, 1), set_acct(1, 1)];
        for s in 0..50_000u16 {
            genesis.push(set_slot(200, s, 5 + s as u64));
        }
        let mut oracle =
            FlatMpt::create(format!("{path}.oracle"), mpt_flat_poc::Config::default()).unwrap();
        let (genesis_root, _) = oracle.apply_block(genesis.clone()).unwrap();
        drop(oracle);
        let g = B256::from(genesis_root);
        let s = FlatShadow::init(path, genesis, g).unwrap();
        let shadow: &'static RwLock<FlatShadow> = Box::leak(Box::new(RwLock::new(s)));

        let mut parent = g;
        for round in 0..2u64 {
            let mut ops: Vec<(Key, StateOp)> = vec![set_acct(200, 2 + round)];
            for s in 0..400u16 {
                ops.push(set_slot(200, s * 100, 9_000 + round + s as u64)); // updates
            }
            for s in 0..100u16 {
                ops.push(del_slot(200, 7 + s * 250 + round as u16)); // deletions
            }
            for s in 0..100u16 {
                ops.push(set_slot(200, 50_000 + 200 * round as u16 + s, 3)); // inserts
            }
            let mut w = Worker::new(shadow, parent);
            let (sparse_root, stats) = w
                .finish(ops.clone())
                .unwrap_or_else(|e| panic!("round {round}: sparse failed: {e:#}"));
            let flat_root = shadow.write().root_for(round, parent, ops).unwrap();
            assert_eq!(sparse_root, flat_root, "round {round}");
            eprintln!(
                "round {round}: storage_targets={} rounds={}",
                stats.storage_targets, stats.finish_rounds
            );
            parent = sparse_root;
        }
    }

    /// tip20-shaped churn: hundreds of accounts, slot updates + deletions +
    /// inserts stacked over three blocks (the live-bench stall shape).
    #[test]
    fn sparse_survives_slot_churn() {
        let _guard = worker_statics_guard();
        let dir = tempfile::tempdir().unwrap();
        let path = dir.path().join("churn.flat");
        let path = path.to_str().unwrap();

        let mut genesis: Vec<(Key, StateOp)> = Vec::new();
        for a in 0..250u8 {
            genesis.push(set_acct(a, 1));
            for s in 0..8u16 {
                genesis.push(set_slot(a, s, 100 + s as u64));
            }
        }
        let mut oracle =
            FlatMpt::create(format!("{path}.oracle"), mpt_flat_poc::Config::default()).unwrap();
        let (genesis_root, _) = oracle.apply_block(genesis.clone()).unwrap();
        drop(oracle);
        let g = B256::from(genesis_root);
        let s = FlatShadow::init(path, genesis, g).unwrap();
        let shadow: &'static RwLock<FlatShadow> = Box::leak(Box::new(RwLock::new(s)));

        let mut parent = g;
        for round in 0..3u64 {
            let mut ops: Vec<(Key, StateOp)> = Vec::new();
            for a in 0..250u8 {
                ops.push(set_acct(a, 2 + round));
                // update 2, delete 2 (different ones per round), insert 2 new
                for s in 0..2u16 {
                    ops.push(set_slot(a, s, 1000 * (round + 1) + s as u64));
                }
                for s in 2..4u16 {
                    ops.push(del_slot(a, s + 2 * round as u16));
                }
                for s in 0..2u16 {
                    ops.push(set_slot(a, 50 + 10 * round as u16 + s, 7));
                }
            }
            let mut w = Worker::new(shadow, parent);
            let (sparse_root, stats) = w
                .finish(ops.clone())
                .unwrap_or_else(|e| panic!("round {round}: sparse failed: {e:#}"));
            let flat_root = shadow.write().root_for(round, parent, ops).unwrap();
            assert_eq!(sparse_root, flat_root, "round {round}");
            eprintln!(
                "round {round}: acct_targets={} storage_targets={} rounds={}",
                stats.account_targets, stats.storage_targets, stats.finish_rounds
            );
            parent = sparse_root;
        }
    }

    /// Execution-read reveals: a fresh worker fed exclusively by
    /// `get_value_reveal` / `get_storage_reveal` node captures (the flat_reads
    /// path) must commit without fetching a single proof target itself —
    /// the single-read invariant. Deletions still pull sibling reveals via
    /// the normal fetch flow (mixed coverage is expected there).
    #[test]
    fn sparse_reveals_from_execution_reads() {
        let _guard = worker_statics_guard();
        use alloy_primitives::U256;
        let dir = tempfile::tempdir().unwrap();
        let path = dir.path().join("execreveal.flat");
        let path = path.to_str().unwrap();

        let mut genesis: Vec<(Key, StateOp)> = Vec::new();
        for a in 0..200u8 {
            genesis.push(set_acct(a, 1));
            for s in 0..6u16 {
                genesis.push(set_slot(a, s, 100 + s as u64));
            }
        }
        let mut oracle =
            FlatMpt::create(format!("{path}.oracle"), mpt_flat_poc::Config::default()).unwrap();
        let (genesis_root, _) = oracle.apply_block(genesis.clone()).unwrap();
        drop(oracle);
        let g = B256::from(genesis_root);
        let s = FlatShadow::init(path, genesis, g).unwrap();
        let shadow: &'static RwLock<FlatShadow> = Box::leak(Box::new(RwLock::new(s)));

        let snap = shadow.read().db().snapshot();
        let mut w = Worker::new(shadow, g);
        assert!(!w.stats.pool_hit, "fresh worker expected");

        // The "block": update accounts 0..200 and slots 0..2 of each. Feed the
        // worker exactly what flat_reads would: the read-walk's nodes.
        let mut ops: Vec<(Key, StateOp)> = Vec::new();
        for a in 0..200u8 {
            let acct = B256::from(akey(a));
            let (v, nodes) = snap.get_value_reveal(&acct.0).unwrap();
            assert!(v.is_some());
            w.on_reveal(RevealBatch::Account { key: acct, nodes });
            ops.push(set_acct(a, 9));
            for s in 0..2u16 {
                let slot_key = keccak256(U256::from(s).to_be_bytes::<32>());
                let (v, nodes) = snap.get_storage_reveal(&acct.0, &slot_key.0).unwrap();
                assert!(v.is_some());
                w.on_reveal(RevealBatch::Storage {
                    account: acct,
                    slot: slot_key,
                    nodes: nodes.expect("transparent storage"),
                });
                ops.push(set_slot(a, s, 5000 + s as u64));
            }
        }
        ops.sort_by_key(|a| a.0);

        let (root, stats) = w.finish(ops.clone()).unwrap();
        let expect = shadow.write().root_for(0, g, ops).unwrap();
        assert_eq!(root, expect, "sink-revealed commit diverges");
        assert_eq!(
            (stats.account_targets, stats.storage_targets),
            (0, 0),
            "worker fetched targets despite execution-read reveals"
        );
    }

    /// Streaming path: hook-fed `Changed` values applied during execution
    /// must leave the trie exactly where the ops drain would — including
    /// intra-block churn (slot rewritten across txs) and A→B→A reverts
    /// (bundle nets present==original but keeps the entry, so the op
    /// restores the streamed intermediate). Exec passes run between batches
    /// like the worker loop does.
    #[test]
    fn sparse_streaming_matches_flat_apply() {
        let _guard = worker_statics_guard();
        use alloy_primitives::U256;
        use revm::state::{Account as EvmAccount, AccountInfo, AccountStatus, EvmStorageSlot};

        let dir = tempfile::tempdir().unwrap();
        let path = dir.path().join("stream.flat");
        let path = path.to_str().unwrap();

        let mut genesis: Vec<(Key, StateOp)> = Vec::new();
        for a in 0..100u8 {
            genesis.push(set_acct(a, 1));
            for s in 0..4u16 {
                genesis.push(set_slot(a, s, 100 + s as u64));
            }
        }
        let mut oracle =
            FlatMpt::create(format!("{path}.oracle"), mpt_flat_poc::Config::default()).unwrap();
        let (genesis_root, _) = oracle.apply_block(genesis.clone()).unwrap();
        drop(oracle);
        let g = B256::from(genesis_root);
        let s = FlatShadow::init(path, genesis, g).unwrap();
        let shadow: &'static RwLock<FlatShadow> = Box::leak(Box::new(RwLock::new(s)));

        let addr = |b: u8| alloy_primitives::Address::from([b; 20]);
        let slot_u = |s: u16| U256::from(s);
        let evm_state = |b: u8, writes: &[(u16, u64, u64)]| {
            // (slot, original, present) per write
            let mut storage = revm::primitives::StorageKeyMap::default();
            for (sl, orig, pres) in writes {
                storage.insert(
                    slot_u(*sl),
                    EvmStorageSlot {
                        original_value: U256::from(*orig),
                        present_value: U256::from(*pres),
                        ..Default::default()
                    },
                );
            }
            let mut acct = EvmAccount::from(AccountInfo {
                nonce: 2,
                balance: U256::from(5000u64),
                ..Default::default()
            });
            acct.storage = storage;
            acct.status = AccountStatus::Touched;
            acct.mark_touch();
            let mut st = revm::state::EvmState::default();
            st.insert(addr(b), acct);
            st
        };

        let mut w = Worker::new(shadow, g);
        // tx batch 1: every account writes slot0 100→7777 (intermediate) and
        // slot1 101→11.
        for a in 0..100u8 {
            w.on_state(evm_state(a, &[(0, 100, 7777), (1, 101, 11)]));
        }
        w.reveal_pass(false).unwrap();
        // tx batch 2: slot0 reverts 7777→100 (A→B→A), slot2 102→22,
        // slot3 cleared 103→0.
        for a in 0..100u8 {
            w.on_state(evm_state(a, &[(0, 7777, 100), (2, 102, 22), (3, 103, 0)]));
        }
        w.reveal_pass(false).unwrap();

        // Net ops, as bundle_to_ops would emit them: A→B→A keeps its entry.
        let mut ops: Vec<(Key, StateOp)> = Vec::new();
        for a in 0..100u8 {
            ops.push(set_acct(a, 2));
            ops.push(set_slot(a, 0, 100));
            ops.push(set_slot(a, 1, 11));
            ops.push(set_slot(a, 2, 22));
            ops.push(del_slot(a, 3));
        }
        let (sparse_root, _) = w.finish(ops.clone()).unwrap();
        let flat_root = shadow.write().root_for(0, g, ops).unwrap();
        assert_eq!(
            sparse_root, flat_root,
            "streamed values diverge from ops drain"
        );
    }
}

#[cfg(test)]
mod proofbench {
    use super::*;
    use reth_trie::Nibbles;

    #[test]
    #[ignore]
    fn proofbench_probe() {
        let path = std::env::var("PROOFBENCH_FLAT").expect("set PROOFBENCH_FLAT");
        let mpt = mpt_flat_poc::FlatMpt::open(&path).expect("open bench flat");
        eprintln!("root: 0x{}", mpt_flat_poc::hex(mpt.root()));
        let mut c = mpt.account_cursor();
        let mut k = [0u8; 32];
        let mut n = 0u64;
        while let Some(e) = c.seek(&k).unwrap() {
            n += 1;
            if n <= 3 {
                eprintln!("acct[{n}]: 0x{}", mpt_flat_poc::hex(e.key));
            }
            if n >= 100_000 {
                break;
            }
            k = e.key;
            // advance
            let mut carry = 1u16;
            for b in k.iter_mut().rev() {
                let v = *b as u16 + carry;
                *b = v as u8;
                carry = v >> 8;
                if carry == 0 {
                    break;
                }
            }
        }
        eprintln!("accounts seen (cap 100k): {n}");
    }

    /// Cold proof-fetch thread sweep over a 1B flat (env PROOFBENCH_FLAT
    /// points at a scratch COPY — FlatMpt::open takes write access).
    /// Run: PROOFBENCH_FLAT=/mnt2/proofbench.flat cargo test -p tempo-flatmpt \
    ///        --release cold_proof_thread_sweep -- --ignored --nocapture
    #[test]
    #[ignore]
    fn cold_proof_thread_sweep() {
        let path = std::env::var("PROOFBENCH_FLAT").expect("set PROOFBENCH_FLAT");
        let mpt = mpt_flat_poc::FlatMpt::open(&path).expect("open bench flat");
        const K: usize = 8_192;
        let contract: B256 = "0x2698635f2d1ac2fffe298dd19560c4be0519bb8894fb4008b21668355dc7b6f1"
            .parse()
            .unwrap();
        for (round, threads) in [12usize, 24, 32, 48, 12].into_iter().enumerate() {
            // Fresh pseudo-random account targets per round (cold: 1B keyspace
            // >> page cache; exclusion proofs exercise the same record-read
            // path as storage targets in a giant contract).
            let mut keys: Vec<B256> = (0..K)
                .map(|i| B256::from(keccak256(format!("proofbench-{round}-{i}"))))
                .collect();
            keys.sort_unstable();
            let chunk_size = K.div_ceil(threads);
            let t = Instant::now();
            let n_nodes: usize = std::thread::scope(|s| {
                let handles: Vec<_> = keys
                    .chunks(chunk_size)
                    .map(|slice| {
                        let mpt = &mpt;
                        s.spawn(move || {
                            let mut t = MultiProofTargetsV2::default();
                            t.storage_targets.insert(
                                contract,
                                slice.iter().map(|k| ProofV2Target::new(*k)).collect(),
                            );
                            Proof::new(
                                crate::cursors::FlatTrieCursorFactory { mpt },
                                crate::cursors::FlatHashedCursorFactory { mpt },
                            )
                            .multiproof_v2(t)
                            .map(|p| p.storage_proofs.values().map(|v| v.len()).sum::<usize>())
                        })
                    })
                    .collect();
                handles
                    .into_iter()
                    .map(|h| h.join().expect("chunk panicked").expect("proof failed"))
                    .sum()
            });
            let ms = t.elapsed().as_millis().max(1);
            eprintln!(
                "proof-walk threads={threads:2} {K} targets in {ms:6} ms -> {:6} targets/s ({} nodes)",
                K as u128 * 1000 / ms,
                n_nodes
            );
            let _ = Nibbles::default();
        }

        // Direct reveal (fast path), same shape: fresh random targets per
        // round, single-threaded then chunk-parallel.
        for (round, threads) in [
            (100usize, 1usize),
            (101, 8),
            (102, 16),
            (103, 24),
            (104, 32),
            (105, 48),
            (106, 64),
        ] {
            let keys: Vec<mpt_flat_poc::Key> = (0..K)
                .map(|i| keccak256(format!("proofbench-{round}-{i}")).0)
                .collect();
            let mut sorted = keys.clone();
            sorted.sort_unstable();
            let t = Instant::now();
            let n_nodes: usize = if threads == 1 {
                to_v2_nodes(
                    mpt.reveal_storage_paths(&contract.0, &sorted)
                        .unwrap()
                        .unwrap(),
                )
                .unwrap()
                .len()
            } else {
                let chunk = K.div_ceil(threads);
                std::thread::scope(|s| {
                    sorted
                        .chunks(chunk)
                        .map(|c| {
                            let mpt = &mpt;
                            let contract = &contract;
                            s.spawn(move || {
                                to_v2_nodes(
                                    mpt.reveal_storage_paths(&contract.0, c).unwrap().unwrap(),
                                )
                                .unwrap()
                                .len()
                            })
                        })
                        .collect::<Vec<_>>()
                        .into_iter()
                        .map(|h| h.join().unwrap())
                        .sum()
                })
            };
            let us = t.elapsed().as_micros().max(1);
            eprintln!(
                "direct-reveal threads={threads:2} {K} targets in {:6} ms -> {:7} targets/s ({} nodes)",
                us / 1000,
                K as u128 * 1_000_000 / us,
                n_nodes
            );
        }
    }
}

#[cfg(test)]
mod overlay_tests {
    use super::{tests::*, *};
    use crate::FlatShadow;
    use mpt_flat_poc::FlatMpt;

    /// THE overlay gate: the follower lags (flat stays at genesis) while two
    /// blocks are committed on top of it — proofs for block 2 (and 3) must be
    /// served by flat@genesis + the overlay stack, and the roots must match
    /// an oracle that applies the same blocks for real.
    #[test]
    fn sparse_commits_ahead_of_lagging_follower() {
        let _guard = tests::worker_statics_guard();
        let dir = tempfile::tempdir().unwrap();
        let path = dir.path().join("overlay.flat");
        let path = path.to_str().unwrap();

        let mut genesis: Vec<(Key, StateOp)> = (0..200u8).map(|i| set_acct(i, 1)).collect();
        for sl in 0..600u16 {
            genesis.push(set_slot(2, sl, 1 + sl as u64));
        }
        let mut oracle =
            FlatMpt::create(format!("{path}.oracle"), mpt_flat_poc::Config::default()).unwrap();
        let (genesis_root, _) = oracle.apply_block(genesis.clone()).unwrap();
        let g = B256::from(genesis_root);
        let s = FlatShadow::init(path, genesis, g).unwrap();
        let shadow: &'static RwLock<FlatShadow> = Box::leak(Box::new(RwLock::new(s)));

        // Three stacked blocks; the shadow is NEVER advanced (lagging
        // follower), so blocks 2 and 3 exercise the overlay path.
        let mut parent = g;
        for round in 0..3u64 {
            let mut ops: Vec<(Key, StateOp)> = vec![
                set_acct(5, 10 + round),
                set_acct((210 + round) as u8, 1), // new account each round
                set_acct(2, 5 + round),
            ];
            for sl in 0..40u16 {
                ops.push(set_slot(2, sl * 9 + round as u16, 7_000 + round));
            }
            for sl in 0..10u16 {
                ops.push(del_slot(2, 13 + sl * 31 + round as u16));
            }
            let mut w = Worker::new(shadow, parent);
            let (sparse_root, _) = w
                .finish(ops.clone())
                .unwrap_or_else(|e| panic!("round {round}: sparse failed: {e:#}"));
            let (oracle_root, _) = oracle
                .apply_block({
                    let mut o = ops.clone();
                    o.sort_by_key(|a| a.0);
                    o
                })
                .unwrap();
            assert_eq!(sparse_root, B256::from(oracle_root), "round {round}");
            assert_ne!(parent, sparse_root);
            parent = sparse_root;
        }
        // The shadow really did lag the whole time.
        assert_eq!(shadow.read().current_root(), g);
    }

    /// The r65/66 killer: a contract whose storage exists ONLY in un-applied
    /// overlay blocks (created at block 1, follower lagging), proven by a
    /// pool-miss worker at block 2. The overlay's TrieUpdates carry no root
    /// node for that storage trie, so the proof historically arrived rootless
    /// and reveal errored "sparse trie is blind" — leaving a blind trie whose
    /// finish PANICKED (reth storage_trie_updates unwrap) and killing the
    /// worker for every subsequent block.
    #[test]
    fn sparse_survives_overlay_created_storage() {
        // The worker machinery shares process-wide statics (TRIE_POOL,
        // OVERLAYS, SNAP_POOL); this test both consumes and pollutes them,
        // so isolate it from concurrently-running worker tests.
        let _guard = tests::worker_statics_guard();
        let dir = tempfile::tempdir().unwrap();
        let path = dir.path().join("ovlnew.flat");
        let path = path.to_str().unwrap();

        let mut genesis: Vec<(Key, StateOp)> = (0..64u8).map(|i| set_acct(i, 1)).collect();
        for sl in 0..100u16 {
            genesis.push(set_slot(2, sl, 1 + sl as u64));
        }
        let mut oracle =
            FlatMpt::create(format!("{path}.oracle"), mpt_flat_poc::Config::default()).unwrap();
        let (genesis_root, _) = oracle.apply_block(genesis.clone()).unwrap();
        let g = B256::from(genesis_root);
        let s = FlatShadow::init(path, genesis, g).unwrap();
        let shadow: &'static RwLock<FlatShadow> = Box::leak(Box::new(RwLock::new(s)));

        // Block 1: contract 201 is born WITH storage. Follower never applies.
        let mut ops1: Vec<(Key, StateOp)> = vec![set_acct(201, 1)];
        for sl in 0..8u16 {
            ops1.push(set_slot(201, sl, 900 + sl as u64));
        }
        ops1.sort_by_key(|a| a.0);
        let mut w1 = Worker::new(shadow, g);
        let (root1, _) = w1.finish(ops1.clone()).unwrap();
        let (o1, _) = oracle.apply_block(ops1).unwrap();
        assert_eq!(root1, B256::from(o1));

        // Cancelled candidate: the pooled trie is gone; block 2's worker is
        // fresh and must prove 201's slots through the overlay chain.
        *TRIE_POOL.lock() = None;
        let mut ops2: Vec<(Key, StateOp)> = vec![set_acct(201, 2), set_acct(3, 7)];
        for sl in 0..4u16 {
            ops2.push(set_slot(201, sl, 7000 + sl as u64));
        }
        ops2.sort_by_key(|a| a.0);
        let mut w2 = Worker::new(shadow, root1);
        assert!(!w2.stats.pool_hit, "block 2 must be a pool miss");
        let (root2, _) = w2
            .finish(ops2.clone())
            .unwrap_or_else(|e| panic!("overlay-created storage proof failed: {e:#}"));
        let (o2, _) = oracle.apply_block(ops2).unwrap();
        assert_eq!(root2, B256::from(o2), "root diverges");
        assert_eq!(shadow.read().current_root(), g, "follower must have lagged");
    }

    /// The r148 block-349 divergence: the pooled trie is lost while the
    /// follower lags, an EMPTY block recreates it blind (pool-hit for its
    /// descendants, anchor pending), and the next op block's targets overlap
    /// state the un-applied blocks changed. The old `pool_hit ⇒ any lineage
    /// root` rule let direct_reveal serve those targets from the lagging
    /// snapshot — pre-update siblings, silently wrong root. The anchor gate
    /// must force the overlay proof path instead.
    #[test]
    fn young_pooled_trie_never_reveals_from_stale_snapshot() {
        let _guard = tests::worker_statics_guard();
        let dir = tempfile::tempdir().unwrap();
        let path = dir.path().join("anchor.flat");
        let path = path.to_str().unwrap();

        let mut genesis: Vec<(Key, StateOp)> = (0..64u8).map(|i| set_acct(i, 1)).collect();
        for sl in 0..200u16 {
            genesis.push(set_slot(2, sl, 1 + sl as u64));
        }
        let mut oracle =
            FlatMpt::create(format!("{path}.oracle"), mpt_flat_poc::Config::default()).unwrap();
        let (genesis_root, _) = oracle.apply_block(genesis.clone()).unwrap();
        let g = B256::from(genesis_root);
        let s = FlatShadow::init(path, genesis, g).unwrap();
        let shadow: &'static RwLock<FlatShadow> = Box::leak(Box::new(RwLock::new(s)));

        // Block 1 (the "flood"): rewrites contract 2's slots and some
        // accounts. The follower never applies it.
        let mut ops1: Vec<(Key, StateOp)> = vec![set_acct(5, 42), set_acct(7, 43)];
        for sl in 0..40u16 {
            ops1.push(set_slot(2, sl, 100_000 + sl as u64));
        }
        let mut w1 = Worker::new(shadow, g);
        let (root1, _) = w1.finish(ops1.clone()).unwrap();
        let (o1, _) = oracle
            .apply_block({
                let mut o = ops1.clone();
                o.sort_by_key(|a| a.0);
                o
            })
            .unwrap();
        assert_eq!(root1, B256::from(o1), "block 1 diverged");

        // Flood-end steal: a raced build consumed the trie and died with it.
        *TRIE_POOL.lock() = None;

        // Empty block on root1: fresh blind trie, pooled with a pending
        // anchor (the follower is still at genesis).
        let mut w2 = Worker::new(shadow, root1);
        assert!(!w2.stats.pool_hit);
        let (root2, _) = w2.finish(Vec::new()).unwrap();
        assert_eq!(root2, root1);

        // Op block on the same root: pool hit on the BLIND trie; its targets
        // overlap block 1's writes, which the lagging snapshot serves stale.
        let mut ops3: Vec<(Key, StateOp)> = vec![set_acct(5, 99)];
        for sl in 0..8u16 {
            ops3.push(set_slot(2, sl * 20, 900_000 + sl as u64));
        }
        ops3.sort_by_key(|a| a.0);
        let mut w3 = Worker::new(shadow, root1);
        assert!(w3.stats.pool_hit, "block 3 must reuse the young trie");
        let (root3, _) = w3.finish(ops3.clone()).unwrap();
        let (o3, _) = oracle.apply_block(ops3).unwrap();
        assert_eq!(
            root3,
            B256::from(o3),
            "stale-snapshot reveal poisoned the root"
        );
        assert_eq!(
            shadow.read().current_root(),
            g,
            "follower must have lagged throughout"
        );
    }

    /// Clean cancelled builds return the trie to the pool; dirty ones don't.
    #[test]
    fn cancelled_build_repools_only_clean_tries() {
        let _guard = tests::worker_statics_guard();
        let dir = tempfile::tempdir().unwrap();
        let path = dir.path().join("repool.flat");
        let path = path.to_str().unwrap();

        let genesis: Vec<(Key, StateOp)> = (0..16u8).map(|i| set_acct(i, 1)).collect();
        let mut oracle =
            FlatMpt::create(format!("{path}.oracle"), mpt_flat_poc::Config::default()).unwrap();
        let (genesis_root, _) = oracle.apply_block(genesis.clone()).unwrap();
        let g = B256::from(genesis_root);
        let s = FlatShadow::init(path, genesis, g).unwrap();
        let shadow: &'static RwLock<FlatShadow> = Box::leak(Box::new(RwLock::new(s)));

        // Clean cancel (reveals only, no updates applied): repooled.
        let w = Worker::new(shadow, g);
        assert!(w.repool_cancelled());
        assert!(TRIE_POOL.lock().is_some());

        // Dirty cancel: dropped, and it must not clobber a pooled entry.
        let mut w = Worker::new(shadow, g); // consumes the pool
        w.dirty = true;
        assert!(!w.repool_cancelled());
        assert!(TRIE_POOL.lock().is_none());
    }
}

#[cfg(test)]
mod finishpath_bench {
    use super::{tests::*, *};
    use alloy_primitives::U256;
    use mpt_flat_poc::{
        FlatMpt,
        eth::{EMPTY_CODE_HASH, storage_value_rlp},
    };

    /// Split worker.finish() into its phases at real 30k-TPS block shape:
    /// ~55k EOA account updates + ~55k slot updates on one hot contract
    /// (r57-flat-b: 29.6k txs, ~110k ops, finish_ms ≈ 69 warm). Block 1 is
    /// cold (proof fetches), blocks 2-3 run on the pooled trie = steady state.
    #[test]
    #[ignore]
    fn finish_phase_split() {
        let dir = tempfile::tempdir().unwrap();
        let path = dir.path().join("phase-split.flat");
        let path = path.to_str().unwrap();

        const EOAS: usize = 55_000;
        const SLOTS: u16 = 55_000_u16;
        let contract: u8 = 251;

        let mut genesis: Vec<(Key, StateOp)> = Vec::new();
        for i in 0..EOAS {
            let a = keccak256(format!("eoa-{i}")).0;
            genesis.push((
                a,
                StateOp::SetAccount {
                    nonce: 1,
                    balance: U256::from(1_000_000u64),
                    code_hash: EMPTY_CODE_HASH.0,
                },
            ));
        }
        genesis.push(set_acct(contract, 1));
        let ckey = akey(contract);
        for s in 0..SLOTS {
            let slot_key = keccak256(U256::from(s).to_be_bytes::<32>()).0;
            genesis.push((
                ckey,
                StateOp::SetStorage {
                    slot: slot_key,
                    value: storage_value_rlp(U256::from(7u64)),
                },
            ));
        }

        let mut oracle =
            FlatMpt::create(format!("{path}.oracle"), mpt_flat_poc::Config::default()).unwrap();
        let (genesis_root, _) = oracle.apply_block(genesis.clone()).unwrap();
        drop(oracle);
        let g = B256::from(genesis_root);

        let s = FlatShadow::init(path, genesis, g).unwrap();
        let shadow: &'static RwLock<FlatShadow> = Box::leak(Box::new(RwLock::new(s)));

        let mut parent = g;
        for round in 1..=3u64 {
            let parent_number = round - 1;
            let mut ops: Vec<(Key, StateOp)> = Vec::with_capacity(EOAS + SLOTS as usize);
            for i in 0..EOAS {
                let a = keccak256(format!("eoa-{i}")).0;
                ops.push((
                    a,
                    StateOp::SetAccount {
                        nonce: 1 + round,
                        balance: U256::from(1_000_000u64 + round),
                        code_hash: EMPTY_CODE_HASH.0,
                    },
                ));
            }
            ops.push(set_acct(contract, 1 + round));
            for s in 0..SLOTS {
                let slot_key = keccak256(U256::from(s).to_be_bytes::<32>()).0;
                ops.push((
                    ckey,
                    StateOp::SetStorage {
                        slot: slot_key,
                        value: storage_value_rlp(U256::from(100 + round)),
                    },
                ));
            }
            ops.sort_by_key(|a| a.0);

            let worker = SparseWorker::begin(shadow, parent);
            let t = Instant::now();
            let (root, st) = worker.finish(ops.clone()).unwrap();
            let total = t.elapsed().as_millis();
            eprintln!(
                "block {round} ({} ops, pool_hit={}): finish={total}ms  \
                 netmap={} drain={} promote={} (sroot={}) root={} overlay={}  (proof={} reveal={})",
                ops.len(),
                st.pool_hit,
                st.fin_netmap_ms,
                st.fin_drain_ms,
                st.fin_promote_ms,
                st.fin_sroot_ms,
                st.fin_root_ms,
                st.fin_overlay_ms,
                st.proof_ms,
                st.reveal_ms,
            );

            // keep the flat store in step so the next round's parent is applied
            let expect = shadow.write().root_for(parent_number, parent, ops).unwrap();
            assert_eq!(root, expect, "sparse/flat divergence in bench");
            parent = root;
        }
    }

    /// Measure the builder's serial finish-path costs at monster-block scale:
    /// bundle-shaped op construction (keccak per address+slot), canonical
    /// sort, and the memo fingerprint (run twice today: queue_apply +
    /// validator).
    #[test]
    #[ignore]
    fn finish_path_costs() {
        for n_tx in [18_000usize, 28_000, 40_000] {
            // tip20-shaped: sender+recipient account op + 2 slots per tx.
            let t = Instant::now();
            let mut ops: Vec<(Key, StateOp)> = Vec::with_capacity(n_tx * 4);
            for i in 0..n_tx {
                let a = keccak256(format!("addr-{i}")).0; // stands in for keccak(address)
                let s1 = keccak256(format!("slot-a-{i}")).0; // keccak(slot)
                let s2 = keccak256(format!("slot-b-{i}")).0;
                ops.push((
                    a,
                    StateOp::SetAccount {
                        nonce: i as u64,
                        balance: alloy_primitives::U256::from(i),
                        code_hash: [0u8; 32],
                    },
                ));
                ops.push((
                    a,
                    StateOp::SetStorage {
                        slot: s1,
                        value: vec![1, 2, 3],
                    },
                ));
                ops.push((
                    a,
                    StateOp::SetStorage {
                        slot: s2,
                        value: vec![4, 5, 6],
                    },
                ));
            }
            let build_ms = t.elapsed().as_micros() as f64 / 1000.0;

            let t = Instant::now();
            ops.sort_by_key(|a| a.0);
            let sort_ms = t.elapsed().as_micros() as f64 / 1000.0;

            let t = Instant::now();
            let _fp = crate::ops_fingerprint(&ops);
            let fp_ms = t.elapsed().as_micros() as f64 / 1000.0;

            eprintln!(
                "n_tx={n_tx:6} ops={:6}: build(keccaks)={build_ms:7.1}ms sort={sort_ms:6.1}ms fingerprint={fp_ms:6.1}ms  (fp runs 2x today; serial total ≈ {:.0}ms)",
                ops.len(),
                build_ms + sort_ms + 2.0 * fp_ms
            );
        }
    }
}
